type AppMenuTab = 'home' | 'agents'
type ProjectDialogMode = 'open' | 'branch' | 'card' | 'release'

interface AppMenuProps {
    accessToken: string | null
    auth: UseGithubAuthResult
    extraActions: ReactNode
    isGithubAuthenticated: boolean
    isMobile: boolean
    onOpenConfig: () => void
    onOpenMobileMenu: () => void
    search: ReactNode
}

const MENU_TABS: { label: string; value: AppMenuTab }[] = [
    { label: 'Home', value: 'home' },
    { label: 'Run', value: 'agents' },
]
const PROJECT_CONTEXT = projectContext()

function persistDesktopConfig() {
    if (!configService.hasDesktopConfig()) return

    writeDesktopConfigToBridge(configService.getDesktopValues())
}

/** Tabbed app menu hosting project, account and agent actions. */
export function AppMenu(props: AppMenuProps) {
    const { accessToken, auth, extraActions, isGithubAuthenticated, isMobile, onOpenConfig, onOpenMobileMenu, search } = props
    const { project } = useProjectState()
    const { hasPendingPush, hasPendingSave } = useProjectPersistence()
    const primaryWorktreeStatus = usePrimaryWorktreeStatus()
    const projectConfig = useProjectConfig()
    const { viewMode } = useWorkspaceView()
    const [currentTab, setCurrentTab] = useState<AppMenuTab>('home')
    const [dialogMode, setDialogMode] = useState<ProjectDialogMode | null>(null)
    const agentProfiles = mergeAgentProfiles(useConfigValue('desktop.agentProfiles'))
    const selectedAgent = useConfigValue('desktop.agent')
    const selectedProfile = findAgentProfile(agentProfiles, selectedAgent)
    const selectedModels = selectedProfile?.models ?? []
    const configuredModel = useConfigValue('desktop.model')
    const selectedThinkingLevel = useConfigValue('desktop.thinkingLevel')
    const selectedPermissionMode = useConfigValue('desktop.permissionMode')
    const desktopAvailable = useHasDesktopConfig()
    const selectedModel = configuredModel || (selectedProfile ? defaultModelForProfile(selectedProfile) : '')
    const projectBranch = project?.branch ?? ''
    const readOnly = useProjectReadOnly()

    const closeDialog = useCallback(() => {
        setDialogMode(null)
    }, [])

    const openDialog = useCallback((mode: ProjectDialogMode) => {
        setDialogMode(mode)
    }, [])

    const actions = useProjectToolbarMenuActions({
        accessToken,
        isGithubAuthenticated,
        onCloseDialog: closeDialog,
        onOpenDialog: openDialog,
    })
    const branchOptions = actions.branches.length > 0 ? actions.branches : (project ? [{ name: project.branch }] : [])
    const selectedBranch = branchOptions.some((branch) => branch.name === actions.switchBranch) ? actions.switchBranch : projectBranch

    const handleTabChange = (_event: SyntheticEvent, value: AppMenuTab) => {
        setCurrentTab(value)
    }

    const handleOpenProject = () => {
        actions.openProjectDialog()
    }

    const handleCreateProjectFolders = (projectFolder: string) => {
        void actions.createProjectFolders(projectFolder)
    }

    const handleLoadBranches = () => {
        void actions.loadSwitchBranches()
    }

    const handleBranchChange = (event: SelectChangeEvent) => {
        void actions.switchProjectBranch(event.target.value)
    }

    const handleOpenReleaseDialog = () => {
        void actions.openReleaseDialog()
    }

    const handleOpenCardDialog = () => {
        actions.openNewCardDialog()
    }

    const handleCommit = async () => {
        try {
            await actions.commit()
        } catch {
            // ProjectSessionService emits the user-visible error.
        }
    }

    const handlePush = async () => {
        try {
            await actions.push()
        } catch {
            // ProjectSessionService emits the user-visible error.
        }
    }

    const handlePull = async () => {
        try {
            await actions.pull()
        } catch {
            // ProjectSessionService emits the user-visible error.
        }
    }

    const handleViewModeChange = (_event: ReactMouseEvent<HTMLElement>, nextMode: WorkspaceViewMode | null) => {
        if (!nextMode) return

        workspaceViewService.setViewMode(nextMode)
    }

    const handleAgentChange = (event: SelectChangeEvent) => {
        const profile = findAgentProfile(agentProfiles, event.target.value)
        const nextModel = profile ? defaultModelForProfile(profile) : ''
        configService.set('desktop.agent', event.target.value)
        configService.set('desktop.model', nextModel)
        persistDesktopConfig()
    }

    const setModel = (value: string) => {
        configService.set('desktop.model', value)
        persistDesktopConfig()
    }

    const handleModelSelectChange = (event: SelectChangeEvent) => {
        setModel(event.target.value)
    }

    const handleModelTextChange = (event: ChangeEvent<HTMLInputElement>) => {
        setModel(event.target.value)
    }

    const handleThinkingLevelChange = (event: SelectChangeEvent) => {
        const thinkingLevel = validateThinkingLevel(event.target.value, 'Default reasoning level')
        configService.set('desktop.thinkingLevel', thinkingLevel)
        persistDesktopConfig()
    }

    const handlePermissionModeChange = (event: SelectChangeEvent) => {
        const permissionMode = validatePermissionMode(event.target.value, 'Default permission mode')
        configService.set('desktop.permissionMode', permissionMode)
        persistDesktopConfig()
    }

    const handleCreateAction = async () => {
        try {
            if (!projectConfig) throw new Error('Cannot create an action before project config is loaded')

            const { definition, path } = actionService.createDefinition(projectConfig.actionsFolder)
            await actionService.saveDefinition(path, definition)
            workspaceViewService.setViewMode('text')
            workspaceNavigationService.open(path)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Action creation failed' })
        }
    }

    const handleDiscardGithubPendingCommits = () => {
        if (!actions.pendingGithubConflictProject) return

        projectSessionService.discardGithubPendingCommits(actions.pendingGithubConflictProject, accessToken)
    }

    const menuTabs = (
        <Tabs
            aria-label="Application menu"
            onChange={handleTabChange}
            scrollButtons={false}
            sx={{
                minHeight: 44,
                '& .MuiTabs-indicator': { height: 2 },
            }}
            value={currentTab}
            variant="scrollable"
        >
            {MENU_TABS.map((tab) => (
                <MuiTab
                    key={tab.value}
                    label={tab.label}
                    sx={{ fontSize: 13.5, minHeight: 44, minWidth: 0, px: 1.5, textTransform: 'none' }}
                    value={tab.value}
                />
            ))}
        </Tabs>
    )

    const viewSection = (
        <Section label="View">
            <ToggleButtonGroup
                exclusive
                onChange={handleViewModeChange}
                size="small"
                sx={{
                    bgcolor: 'action.selected',
                    borderRadius: 1,
                    gap: 0.25,
                    p: 0.375,
                    '& .MuiToggleButtonGroup-grouped': { border: 0, borderRadius: '6px !important', height: 28, px: 1.25 },
                    '& .Mui-selected': { bgcolor: 'background.paper', boxShadow: '0 1px 2px rgba(16,24,40,0.1)' },
                }}
                value={viewMode}
            >
                <Tooltip title="Cards view">
                    <ToggleButton aria-label="Cards view" value="cards">
                        <CardsOutline fontSize="small" />
                        <Box component="span" sx={{ ml: 0.75 }}>Board</Box>
                    </ToggleButton>
                </Tooltip>
                <Tooltip title="Text view">
                    <ToggleButton aria-label="Text view" value="text">
                        <TextBoxOutline fontSize="small" />
                        <Box component="span" sx={{ ml: 0.75 }}>List</Box>
                    </ToggleButton>
                </Tooltip>
            </ToggleButtonGroup>
        </Section>
    )

    const menuPanel = (
        <Menu>
            <Box role="tabpanel" sx={{ display: currentTab === 'home' ? 'block' : 'none' }}>
                <Tab>
                    {isMobile ? (
                        <>
                            {viewSection}
                            <Divider flexItem orientation="vertical" sx={{ my: 1.5 }} />
                        </>
                    ) : null}
                    <Section label="Project">
                        <MenuIconButton label="Open project" onClick={handleOpenProject}>
                            <FolderOpen fontSize="small" />
                        </MenuIconButton>
                        <BranchMenuSelect
                            branches={branchOptions}
                            disabled={!actions.isProjectOpen || actions.isLoading}
                            onChange={handleBranchChange}
                            onOpen={handleLoadBranches}
                            value={selectedBranch}
                        />
                        <MenuIconButton
                            disabled={readOnly || !actions.isProjectOpen || actions.isLoading || !hasPendingSave}
                            label="Commit"
                            onClick={handleCommit}
                        >
                            <ContentSaveOutline fontSize="small" />
                        </MenuIconButton>
                        <MenuIconButton
                            disabled={
                                !actions.isProjectOpen
                                || readOnly
                                || actions.isLoading
                                || (!hasPendingPush && (primaryWorktreeStatus?.ahead ?? 0) <= 0)
                            }
                            label="Push"
                            onClick={handlePush}
                        >
                            <CloudArrowUpOutline fontSize="small" />
                        </MenuIconButton>
                        <MenuIconButton
                            disabled={
                                !actions.isProjectOpen
                                || readOnly
                                || actions.isLoading
                                || hasPendingSave
                                || hasPendingPush
                                || !primaryWorktreeStatus?.hasUpstream
                                || primaryWorktreeStatus.dirty
                                || primaryWorktreeStatus.ahead > 0
                                || primaryWorktreeStatus.behind <= 0
                            }
                            label="Pull"
                            onClick={handlePull}
                        >
                            <CloudArrowDownOutline fontSize="small" />
                        </MenuIconButton>
                    </Section>
                    <Divider flexItem orientation="vertical" sx={{ my: 1.5 }} />
                    <Section label="Settings">
                        <MenuIconButton label="Config" onClick={onOpenConfig}>
                            <Cog fontSize="small" />
                        </MenuIconButton>
                        {extraActions}
                    </Section>
                    {!isMobile ? (
                        <>
                            <Divider flexItem orientation="vertical" sx={{ my: 1.5 }} />
                            {viewSection}
                            <Divider flexItem orientation="vertical" sx={{ my: 1.5 }} />
                            <Button disabled={!project || readOnly} onClick={handleCreateAction} size="small" variant="outlined">New action</Button>
                            <Button
                                disabled={!actions.isProjectOpen || readOnly}
                                onClick={handleOpenCardDialog}
                                size="small"
                                startIcon={<FileDocumentPlusOutline fontSize="small" />}
                                sx={{ height: 34, px: 1.75 }}
                                variant="contained"
                            >
                                New card
                            </Button>
                            <Box sx={{ flex: 1 }} />
                            <Section label="Account">
                                <GithubAuthToolbarButton auth={auth} />
                            </Section>
                        </>
                    ) : null}
                </Tab>
            </Box>
            <Box role="tabpanel" sx={{ display: currentTab === 'agents' ? 'block' : 'none' }}>
                <Tab>
                    <Section label="Setup">
                        <MenuSelect
                            disabled={!desktopAvailable}
                            label="Default agent"
                            minWidth={130}
                            onChange={handleAgentChange}
                            value={selectedAgent}
                        >
                            {agentProfiles.map((profile) => (
                                <MenuItem key={profile.name} value={profile.name}>{profile.name}</MenuItem>
                            ))}
                        </MenuSelect>
                        {selectedModels.length > 0 ? (
                            <MenuSelect
                                disabled={!desktopAvailable}
                                label="Default model"
                                minWidth={150}
                                onChange={handleModelSelectChange}
                                value={selectedModel}
                            >
                                {selectedModels.map((model) => (
                                    <MenuItem key={model} value={model}>{model}</MenuItem>
                                ))}
                            </MenuSelect>
                        ) : (
                            <Tooltip title="Default model">
                                <TextField
                                    disabled={!desktopAvailable}
                                    onChange={handleModelTextChange}
                                    size="small"
                                    slotProps={{ htmlInput: { 'aria-label': 'Default model' } }}
                                    style={NO_DRAG_REGION}
                                    sx={{ width: 150 }}
                                    value={selectedModel}
                                />
                            </Tooltip>
                        )}
                        <MenuSelect
                            disabled={!desktopAvailable}
                            label="Default reasoning level"
                            minWidth={120}
                            onChange={handleThinkingLevelChange}
                            value={selectedThinkingLevel}
                        >
                            {THINKING_LEVELS.map((level) => (
                                <MenuItem key={level} value={level}>{level}</MenuItem>
                            ))}
                        </MenuSelect>
                        {selectedProfile && supportsPermissionMode(selectedProfile) ? (
                            <MenuSelect
                                disabled={!desktopAvailable}
                                label="Default permission mode"
                                minWidth={190}
                                onChange={handlePermissionModeChange}
                                value={selectedPermissionMode}
                            >
                                {PERMISSION_MODE_OPTIONS.map(({ label, value }) => (
                                    <MenuItem key={value} value={value}>{label}</MenuItem>
                                ))}
                            </MenuSelect>
                        ) : <TextField disabled size="small" value="Permissions unsupported" />}
                    </Section>
                    <Divider flexItem orientation="vertical" sx={{ my: 1.5 }} />
                    <Section label="Actions">
                        <ActionEntryPoints context={PROJECT_CONTEXT} variant="icons" visibility="explicit-context" />
                        <MenuIconButton
                            disabled={readOnly || !actions.isProjectOpen || actions.activeCards.length === 0 || actions.isReleaseCompleting}
                            label="Complete release"
                            onClick={handleOpenReleaseDialog}
                        >
                            <CheckCircleOutline fontSize="small" />
                        </MenuIconButton>
                    </Section>
                </Tab>
            </Box>
            <ProjectOpenDialog
                branches={actions.branches}
                initialSource={actions.initialProjectSource}
                isDesktopMode={actions.isDesktopMode}
                isGithubAuthenticated={isGithubAuthenticated}
                isLoading={actions.isLoading}
                onChooseLocalFolder={actions.chooseLocalProjectFolder}
                onCreateProjectFolders={handleCreateProjectFolders}
                projectOpenResolution={actions.projectOpenResolution}
                onBranchChange={() => undefined}
                onClose={actions.closeDialog}
                onCreateRemoteProject={actions.createRemoteProject}
                onCreateWorkingFolder={() => void actions.createWorkingFolder()}
                onDiscardGithubPendingCommits={handleDiscardGithubPendingCommits}
                onLoadManualBranches={actions.loadManualBranches}
                onLoadRemoteBranches={actions.loadRemoteBranches}
                onOpenGithub={actions.openGithubProject}
                onOpenLocal={actions.openLocalProject}
                onOpenRemote={actions.openRemoteProject}
                onRepositoryChange={actions.loadRepositoryBranches}
                onSourceChange={actions.clearOpenDialogState}
                onUseWorkingFolder={(folder) => void actions.openWorkingFolder(folder)}
                open={dialogMode === 'open'}
                pendingGithubConflictProject={actions.pendingGithubConflictProject}
                recentLocalRepositories={actions.recentLocalRepositories}
                repositories={actions.repositories}
            />
            <BranchSwitchDialog
                branches={actions.branches}
                isLoading={actions.isLoading}
                onBranchChange={actions.setSwitchBranch}
                onClose={actions.closeDialog}
                onSwitchBranch={(branch) => void actions.switchProjectBranch(branch)}
                open={dialogMode === 'branch'}
                selectedBranch={actions.switchBranch}
            />
            <CompleteReleaseDialog
                branchCandidates={actions.releaseBranchCandidates}
                defaultSelectAll={actions.releaseSelectAllDefault}
                isLoading={actions.isLoading}
                key={dialogMode === 'release' ? 'release-open' : 'release-closed'}
                onClose={actions.closeDialog}
                onCompleteRelease={actions.completeRelease}
                onSelectAllDefaultChange={actions.setReleaseSelectAllDefault}
                open={dialogMode === 'release'}
            />
            <NewCardDialog
                cardTypes={actions.cardTypes}
                initialTargetStatus={actions.newCardInitialStatus}
                isLoading={actions.isLoading}
                isProjectOpen={actions.isProjectOpen}
                onClose={actions.closeDialog}
                onCreateCard={actions.createCard}
                open={dialogMode === 'card'}
                states={actions.states}
            />
        </Menu>
    )

    return (
        <MainToolbar
            isMobile={isMobile}
            mobileAction={isMobile && currentTab === 'home' ? (
                <MobileCreateMenu
                    isNewActionDisabled={!project || readOnly}
                    isNewCardDisabled={!actions.isProjectOpen || readOnly}
                    onCreateAction={handleCreateAction}
                    onCreateCard={handleOpenCardDialog}
                />
            ) : null}
            onOpenMenu={onOpenMobileMenu}
            panel={menuPanel}
            search={search}
            tabs={menuTabs}
        />
    )
}

function usageNumber(value) {
    return typeof value === 'number' && Number.isFinite(value) && value >= 0 ? value : 0
}

function requireUsageNumber(value, fieldName) {
    if (typeof value !== 'number' || !Number.isFinite(value) || value < 0) {
        throw new Error(`Invalid provider token usage ${fieldName}`)
    }

    return value
}

/**
 * Coerce a provider usage record into the shape `sumAgentTokenUsage` relies on: five finite
 * non-negative counters plus an optional `costUsd`. `totalTokens` is always recomputed from the
 * buckets rather than trusted, so provider totals can never disagree with their own parts.
 */
export function normalizeAgentTokenUsage(value) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return null

    const usage = {
        cachedInputTokens: usageNumber(value.cachedInputTokens),
        inputTokens: usageNumber(value.inputTokens),
        outputTokens: usageNumber(value.outputTokens),
        reasoningTokens: usageNumber(value.reasoningTokens),
    }
    if (value.legacyTotalTokens !== undefined) usage.legacyTotalTokens = usageNumber(value.legacyTotalTokens)
    usage.totalTokens = (usage.legacyTotalTokens ?? 0)
        + usage.inputTokens
        + usage.cachedInputTokens
        + usage.outputTokens
        + usage.reasoningTokens
    if (typeof value.costUsd === 'number' && Number.isFinite(value.costUsd) && value.costUsd >= 0) usage.costUsd = value.costUsd

    return usage
}

/** Validate disjoint usage buckets emitted for one newly completed provider turn. */
export function validateAgentTokenUsage(value, providerTotalTokens) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) {
        throw new Error('Invalid provider token usage')
    }
    const usage = {
        cachedInputTokens: requireUsageNumber(value.cachedInputTokens, 'cachedInputTokens'),
        inputTokens: requireUsageNumber(value.inputTokens, 'inputTokens'),
        outputTokens: requireUsageNumber(value.outputTokens, 'outputTokens'),
        reasoningTokens: requireUsageNumber(value.reasoningTokens, 'reasoningTokens'),
    }
    usage.totalTokens = usage.inputTokens + usage.cachedInputTokens + usage.outputTokens + usage.reasoningTokens
    if (providerTotalTokens !== undefined) {
        const totalTokens = requireUsageNumber(providerTotalTokens, 'totalTokens')
        if (usage.totalTokens !== totalTokens) {
            throw new Error(`Inconsistent provider token usage total: expected ${totalTokens}, received ${usage.totalTokens}`)
        }
    }
    if (value.costUsd !== undefined) usage.costUsd = requireUsageNumber(value.costUsd, 'costUsd')

    return usage
}

/** Sum normalized agent token usage records, skipping absent entries; costUsd only appears when a provider reported one. */
export function sumAgentTokenUsage(usages) {
    const total = { cachedInputTokens: 0, inputTokens: 0, outputTokens: 0, reasoningTokens: 0, totalTokens: 0 }
    let hasReportedCost = false
    let hasLegacyTotal = false

    for (const usage of usages) {
        if (!usage) continue

        total.cachedInputTokens += usage.cachedInputTokens
        total.inputTokens += usage.inputTokens
        total.outputTokens += usage.outputTokens
        total.reasoningTokens += usage.reasoningTokens
        total.totalTokens += usage.totalTokens
        if (usage.legacyTotalTokens !== undefined) {
            total.legacyTotalTokens = (total.legacyTotalTokens ?? 0) + usage.legacyTotalTokens
            hasLegacyTotal = true
        }
        if (usage.costUsd !== undefined) {
            total.costUsd = (total.costUsd ?? 0) + usage.costUsd
            hasReportedCost = true
        }
    }
    if (!hasReportedCost) delete total.costUsd
    if (!hasLegacyTotal) delete total.legacyTotalTokens

    return total
}

import type { CardActivityFile } from '../../../../shared/card_activity.mjs'
import { parseActivityFileForMigration } from '../../../../shared/card_activity.mjs'
import {
    addSummaryUsage,
    agentTokenUsageFilePath,
    createAgentTokenUsageSummary,
    emptySummaryUsage,
    legacySummaryUsage,
    parseAgentTokenUsageSummary,
    serializeAgentTokenUsageSummary,
    type AgentTokenUsageSummary,
} from '../../../../shared/agent_token_usage_summary.mjs'
import type { ProjectConfig, ProjectReference, ProjectWatchEvent, StorageService } from '../../data/data_types'

const CARD_ACTIVITY_FILE = /(?:^|\/)card__[^/]+\.json$/u

interface LoadedProjectUsage {
    config: ProjectConfig
    project: ProjectReference
    reportFailure: (error: unknown) => void
    storage: StorageService
}

function releaseNameForActivity(activityPath: string, releasesFolder: string) {
    const normalizedActivityPath = activityPath.replace(/\\/gu, '/')
    const normalizedReleasesFolder = releasesFolder.replace(/\\/gu, '/').replace(/^\/+|\/+$/gu, '')
    const prefix = `${normalizedReleasesFolder}/`
    if (!normalizedActivityPath.startsWith(prefix)) return null
    const releaseName = normalizedActivityPath.slice(prefix.length).split('/')[0]

    return releaseName.length > 0 ? releaseName : null
}

function legacyActivityUsage(activity: CardActivityFile) {
    const hasCost = activity.conversations.some((conversation) => conversation.usage?.costUsd !== undefined)
    const costUsd = activity.conversations.reduce((total, conversation) => total + (conversation.usage?.costUsd ?? 0), 0)
    const totalTokens = activity.conversations.reduce((total, conversation) => total + (conversation.usage?.totalTokens ?? 0), 0)

    return legacySummaryUsage(totalTokens, hasCost ? costUsd : undefined)
}

export function createProjectAgentTokenUsageFile(projectFolder: string) {
    return {
        content: serializeAgentTokenUsageSummary(createAgentTokenUsageSummary()),
        path: agentTokenUsageFilePath(projectFolder),
    }
}

// TEMPORARY: Internal migration only. Remove after existing internal projects have generated their summary file.
async function migrateProjectSummary(
    project: ProjectReference,
    config: ProjectConfig,
    storage: StorageService,
    repositoryFiles: string[],
) {
    if (!storage.loadTextFile) throw new Error('Repository text file loading is not available')
    const activityPaths = repositoryFiles.filter((path) => CARD_ACTIVITY_FILE.test(path.replace(/\\/gu, '/')))
    const projectUsages = []
    const releaseUsages = new Map<string, ReturnType<typeof emptySummaryUsage>[]>()
    for (const activityPath of activityPaths) {
        let usage
        try {
            const activityFile = await storage.loadTextFile(project, activityPath)
            usage = legacyActivityUsage(parseActivityFileForMigration(activityFile.content))
        } catch {
            continue
        }
        projectUsages.push(usage)
        const releaseName = releaseNameForActivity(activityPath, config.releasesFolder)
        if (!releaseName) continue
        releaseUsages.set(releaseName, [...(releaseUsages.get(releaseName) ?? []), usage])
    }
    const releases = Object.fromEntries(
        [...releaseUsages.entries()].map(([name, usages]) => [name, addSummaryUsage(usages)]),
    )

    return createAgentTokenUsageSummary(addSummaryUsage(projectUsages), releases)
}

export class ProjectAgentTokenUsageService extends EventTarget {
    private loadedProject: LoadedProjectUsage | null = null
    private operationPromise: Promise<void> | null = null
    private pendingRepositoryChange: ProjectWatchEvent['changeKind'] | null = null
    private repositoryChangeInProgress: ProjectWatchEvent['changeKind'] | null = null
    private repositoryRefreshProject: LoadedProjectUsage | null = null
    private repositoryRefreshPromise: Promise<void> | null = null
    private summary: AgentTokenUsageSummary | null = null

    getSnapshot = () => this.summary

    subscribe = (listener: () => void) => {
        this.addEventListener('changed', listener)

        return () => this.removeEventListener('changed', listener)
    }

    clear() {
        this.loadedProject = null
        this.pendingRepositoryChange = null
        this.setSummary(null)
    }

    async load(
        project: ProjectReference,
        config: ProjectConfig,
        storage: StorageService,
        reportFailure: (error: unknown) => void,
    ) {
        const loadedProject = { config, project, reportFailure, storage }
        this.loadedProject = loadedProject
        this.pendingRepositoryChange = null

        await this.enqueueOperation(loadedProject, () => this.loadOrMigrateSummary(loadedProject))
    }

    async refresh(): Promise<void> {
        const loadedProject = this.loadedProject
        if (!loadedProject) return

        await this.enqueueOperation(loadedProject, () => this.loadOrMigrateSummary(loadedProject))
    }

    handleRepositoryChange(event: ProjectWatchEvent) {
        if (!this.loadedProject) return
        const summaryPath = agentTokenUsageFilePath(this.loadedProject.config.projectFolder)
        if (event.path.replace(/\\/gu, '/') !== summaryPath) return
        if (event.changeKind === 'removed'
            && this.repositoryChangeInProgress === 'removed'
            && this.repositoryRefreshProject === this.loadedProject) return

        this.pendingRepositoryChange = event.changeKind
        if (this.repositoryRefreshPromise && this.repositoryRefreshProject === this.loadedProject) return

        const loadedProject = this.loadedProject
        const refreshPromise = this.refreshFromRepositoryChanges(loadedProject)
        this.repositoryRefreshProject = loadedProject
        this.repositoryRefreshPromise = refreshPromise
        void this.handleRepositoryRefreshResult(loadedProject, refreshPromise)
    }

    private async handleRepositoryRefreshResult(
        loadedProject: LoadedProjectUsage,
        refreshPromise: Promise<void>,
    ) {
        try {
            await refreshPromise
        } catch (error) {
            if (this.isCurrentProject(loadedProject)) this.pendingRepositoryChange = null
            loadedProject.reportFailure(error)
        } finally {
            if (this.repositoryRefreshPromise === refreshPromise) {
                this.repositoryRefreshProject = null
                this.repositoryRefreshPromise = null
            }
        }
    }

    private async loadOrMigrateSummary(loadedProject: LoadedProjectUsage) {
        const { config, project, storage } = loadedProject
        const summaryPath = agentTokenUsageFilePath(config.projectFolder)
        const repositoryFiles = await storage.listRepositoryFiles(project)
        if (!this.isCurrentProject(loadedProject)) return
        if (repositoryFiles.includes(summaryPath)) {
            await this.loadStoredSummary(loadedProject)
            return
        }

        await this.migrateAndCommitSummary(loadedProject, repositoryFiles)
    }

    private async loadStoredSummary(loadedProject: LoadedProjectUsage) {
        const { config, project, storage } = loadedProject
        if (!storage.loadTextFile) throw new Error('Repository text file loading is not available')
        const summaryPath = agentTokenUsageFilePath(config.projectFolder)
        try {
            const summaryFile = await storage.loadTextFile(project, summaryPath)
            const summary = parseAgentTokenUsageSummary(summaryFile.content)
            if (!this.isCurrentProject(loadedProject)) return

            this.setSummary(summary)
        } catch (error) {
            const currentRepositoryFiles = await storage.listRepositoryFiles(project)
            if (!this.isCurrentProject(loadedProject)) return
            if (currentRepositoryFiles.includes(summaryPath)) throw error

            await this.migrateAndCommitSummary(loadedProject, currentRepositoryFiles)
        }
    }

    private async migrateAndCommitSummary(loadedProject: LoadedProjectUsage, repositoryFiles: string[]) {
        const { config, project, storage } = loadedProject
        const summaryPath = agentTokenUsageFilePath(config.projectFolder)
        const summary = await migrateProjectSummary(project, config, storage, repositoryFiles)
        if (!this.isCurrentProject(loadedProject)) return
        await storage.commit({
            branch: project.branch,
            files: [{ content: serializeAgentTokenUsageSummary(summary), path: summaryPath }],
            message: 'Add project agent token usage summary',
        })
        if (config.pushMode === 'auto') await storage.push(project)
        if (!this.isCurrentProject(loadedProject)) return

        this.setSummary(summary)
    }

    private async enqueueOperation(loadedProject: LoadedProjectUsage, operation: () => Promise<void>) {
        while (this.operationPromise) {
            const activeOperation = this.operationPromise
            try {
                await activeOperation
            } catch {
                // A queued operation reports through its own caller. Continue with current work.
            }
            if (this.operationPromise === activeOperation) this.operationPromise = null
        }
        if (!this.isCurrentProject(loadedProject)) return

        const operationPromise = operation()
        this.operationPromise = operationPromise
        try {
            await operationPromise
        } finally {
            if (this.operationPromise === operationPromise) this.operationPromise = null
        }
    }

    private isCurrentProject(loadedProject: LoadedProjectUsage) {
        return this.loadedProject === loadedProject
    }

    private async refreshFromRepositoryChanges(loadedProject: LoadedProjectUsage) {
        while (this.isCurrentProject(loadedProject) && this.pendingRepositoryChange) {
            const changeKind = this.pendingRepositoryChange
            this.pendingRepositoryChange = null
            this.repositoryChangeInProgress = changeKind
            try {
                if (changeKind === 'removed') {
                    await this.enqueueOperation(loadedProject, () => this.loadOrMigrateSummary(loadedProject))
                    continue
                }

                await this.enqueueOperation(loadedProject, () => this.loadOrMigrateSummary(loadedProject))
            } finally {
                this.repositoryChangeInProgress = null
            }
        }
    }

    private setSummary(summary: AgentTokenUsageSummary | null) {
        if (this.summary === summary) return
        this.summary = summary
        this.dispatchEvent(new Event('changed'))
    }
}

export const projectAgentTokenUsageService = new ProjectAgentTokenUsageService()

