            this.startProjectWatch()
        } catch (error) {
            reportOptionalProjectLoadFailure('Project file watching', error)
        }
    }

    private async importExternalCardFiles(files: MarkdownFile[], workingFolder: string) {
        if (projectAccessService.getSnapshot()) return files

        const currentProject = this.dependencies.project()
        if (!currentProject) return files

        let nextFiles = files
        while (this.externalCardImportInProgress) {
            const activeImport = this.externalCardImportInProgress
            const result = await activeImport.promise
            const isSameProject = activeImport.project.id === currentProject.id
                && activeImport.project.branch === currentProject.branch
            if (isSameProject) {
                if (!result.succeeded) return nextFiles
                nextFiles = mergeFiles(removeFilesByPath(nextFiles, result.sourcePaths), result.importedFiles)
            }
            if (this.externalCardImportInProgress === activeImport) this.externalCardImportInProgress = null
        }

        const activeProject = this.dependencies.project()
        if (activeProject?.id !== currentProject.id || activeProject.branch !== currentProject.branch) return nextFiles

        const { config } = this.dependencies.requireDependencies()
        const plan = planExternalCardImports(nextFiles, workingFolder, config.cardSeparator, config.cardTypes, config.states[0].state)
        if (plan.moves.length === 0) return nextFiles

        const promise = this.executeExternalCardImport(nextFiles, currentProject, plan)
        const activeImport = { project: currentProject, promise }
        this.externalCardImportInProgress = activeImport

        try {
            const result = await promise

            return result.files
        } finally {
            if (this.externalCardImportInProgress === activeImport) this.externalCardImportInProgress = null
        }
    }

    private async executeExternalCardImport(
        files: MarkdownFile[],
        currentProject: ProjectReference,
        plan: ExternalCardImportPlan,
    ): Promise<ExternalCardImportResult> {
        const { config, storage } = this.dependencies.requireDependencies()

        const importPaths = plan.moves.flatMap((move) => [move.fromPath, move.toPath])
        const sourcePaths = plan.moves.map((move) => move.fromPath)
        const inFlightCommitPaths = this.dependencies.commitPathsInFlight()
        importPaths.forEach((path) => inFlightCommitPaths.add(path))

        try {
            await storage.moveFiles({
                branch: currentProject.branch,
                message: `Import ${plan.moves.length} external ${plan.moves.length === 1 ? 'file' : 'files'}`,
                moves: plan.moves,
            })
        } catch (error) {
            reportWorkspaceError(errorMessage(error, 'External file import failed'))
            telemetryService.captureError(error)

            return { files, importedFiles: [], sourcePaths: [], succeeded: false }
        } finally {
            importPaths.forEach((path) => inFlightCommitPaths.delete(path))
        }

        if (config.pushMode === 'auto') await storage.push(currentProject)
        if (config.pushMode === 'manual') this.dependencies.dispatchPersistenceChanged()

        reportWorkspaceNotice(importedNoticeMessage(plan.moves.length))
        telemetryService.trackEvent('external_file_import')

        const importedFiles = mergeFiles(removeFilesByPath(files, sourcePaths), plan.importedFiles)

        return { files: importedFiles, importedFiles: plan.importedFiles, sourcePaths, succeeded: true }
    }

    private async loadFullProjectInBackground(
        project: ProjectReference,
        projectFolder: string,
        workingFolder: string,
        projectLoadToken: number,
    ) {
        const { storage } = this.dependencies.requireDependencies()
        const [projectFilesResult, repositoryFilesResult] = await Promise.allSettled([
            storage.loadProject(project, projectFolder),
            storage.listRepositoryFiles(project),
        ])
        if (!this.shouldApplyProjectLoad(project, projectLoadToken)) return

        let nextFiles = this.dependencies.files()
        let projectFilesLoaded = false
        if (projectFilesResult.status === 'fulfilled') {
            try {
                const importedFiles = await this.importExternalCardFiles(projectFilesResult.value.files, workingFolder)
                if (!this.shouldApplyProjectLoad(project, projectLoadToken)) return

                const importedPaths = new Set(importedFiles.map((file) => file.path))
                const removedImportedPaths = projectFilesResult.value.files
                    .filter((file) => !importedPaths.has(file.path))
                    .map((file) => file.path)
                const remainingFiles = removeFilesByPath(this.dependencies.files(), removedImportedPaths)
                nextFiles = mergeFiles(importedFiles, remainingFiles)
                projectFilesLoaded = true
            } catch (error) {
                reportWorkspaceError(backgroundProjectLoadFailureMessage(error))
                telemetryService.captureError(error)
            }
        } else {
            reportWorkspaceError(backgroundProjectLoadFailureMessage(projectFilesResult.reason))
            telemetryService.captureError(projectFilesResult.reason)
        }

        const currentRepositoryFiles = this.dependencies.snapshot()?.repositoryFiles ?? []
        const repositoryFiles = repositoryFilesResult.status === 'fulfilled'
            ? repositoryFilesResult.value
            : currentRepositoryFiles
        if (repositoryFilesResult.status === 'rejected') {
            reportOptionalProjectLoadFailure('Repository file index', repositoryFilesResult.reason)
        }
        if (!projectFilesLoaded && repositoryFilesResult.status === 'rejected') return
        if (!this.shouldApplyProjectLoad(project, projectLoadToken)) return

        this.dependencies.mergeBackgroundProjectFiles(nextFiles, workingFolder, repositoryFiles)
        await this.ensureCardInternalIds()
        await this.dependencies.migrateAgentLogReferences()
        if (projectFilesLoaded) this.dependencies.markFullProjectLoaded()
        this.dependencies.dispatchChanged()
    }

    private shouldApplyProjectLoad(project: ProjectReference, projectLoadToken: number) {
        return this.dependencies.isCurrentLoad(project, projectLoadToken)
    }

    private startProjectWatch() {
        this.stopProjectWatch()
        const currentProject = this.dependencies.project()
        const storage = this.dependencies.storage()
        if (!currentProject || !storage?.watchProject) return

        this.watchCleanup = storage.watchProject(
            currentProject,
            (event) => this.handleProjectWatchEvent(event),
            () => void this.resynchronizeProjectAfterWatchRestore(),
            (error) => reportOptionalProjectLoadFailure('Project file watching', error),
        )
    }

    private async resynchronizeProjectAfterWatchRestore() {
        const { config, storage } = this.dependencies.requireDependencies()
        const currentProject = this.dependencies.project()
        if (!currentProject) return

        try {
            const projectFiles = await storage.loadProject(currentProject, config.projectFolder)
            if (this.dependencies.project() !== currentProject) return

            const currentFiles = this.dependencies.files().filter((file) => isProjectMarkdownPath(file.path, config.projectFolder))
            const currentFilesByPath = new Map(currentFiles.map((file) => [file.path, file]))
            const loadedPaths = new Set<string>()
            for (const file of projectFiles.files) {
                if (!isProjectMarkdownPath(file.path, config.projectFolder)) continue

                loadedPaths.add(file.path)
                const currentFile = currentFilesByPath.get(file.path)
                if (currentFile?.content === file.content) continue

                this.handleProjectWatchEvent({
                    changeKind: currentFile ? 'changed' : 'added',
                    path: file.path,
                })
            }
            for (const file of currentFiles) {
                if (!loadedPaths.has(file.path)) this.handleProjectWatchEvent({ changeKind: 'removed', path: file.path })
            }
        } catch (error) {
            reportOptionalProjectLoadFailure('Project resynchronization', error)
        }
    }

    private handleProjectWatchEvent(event: ProjectWatchEvent) {
        if (mergeConflictService.isConflictedPath(event.path)) {
            this.scheduleMergeConflictVerification()
            return
        }
        this.dependencies.updateRepositoryFile(event)
        this.dependencies.dispatchRepositoryChanged(event)
        if (event.path === PROJECT_CONFIG_PATH) {
            void this.reloadProjectConfigFromWatch()
            return
        }
        const { config } = this.dependencies.requireDependencies()
        if (isActionDefinitionPath(event.path, config.actionsFolder)) {
            const change: ActionReloadChange = this.dependencies.commitPathsInFlight().has(event.path)
                ? { origin: 'local', path: event.path, revision: actionService.getPublicationRevision(event.path) }
                : { origin: 'external', path: event.path }
            this.scheduleActionReload(change)
            return
        }

        if (!isProjectMarkdownPath(event.path, config.projectFolder)) return
        if (this.dependencies.commitPathsInFlight().has(event.path)) return

        this.scheduleMarkdownReload(event)
    }

    private async reloadProjectConfigFromWatch() {
        const { storage } = this.dependencies.requireDependencies()
        const currentProject = this.dependencies.project()
        if (!currentProject) return

        try {
            configService.loadProjectConfig(await storage.loadProjectConfig(currentProject))
        } catch (error) {
            reportOptionalProjectLoadFailure('Project configuration reload', error)
        }
    }

    private scheduleActionReload(change: ActionReloadChange) {
        this.actionReloadChangesByPath.set(change.path, change)
        this.clearActionReloadTimeout()
        this.actionReloadTimeout = window.setTimeout(() => {
            void this.reloadActionsFromCurrentProject()
        }, ACTION_RELOAD_DEBOUNCE_MS)
    }

    private scheduleMergeConflictVerification() {
        this.clearMergeConflictVerifyTimeout()
        this.mergeConflictVerifyTimeout = window.setTimeout(() => {
            void this.verifyMergeConflictState()
        }, MERGE_CONFLICT_VERIFY_DEBOUNCE_MS)
    }

    private clearMergeConflictVerifyTimeout() {
        if (this.mergeConflictVerifyTimeout === null) return

        window.clearTimeout(this.mergeConflictVerifyTimeout)
        this.mergeConflictVerifyTimeout = null
    }

    private async verifyMergeConflictState() {
        this.clearMergeConflictVerifyTimeout()
        try {
            await mergeConflictService.verifyCurrentSession()
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Could not verify merge conflict state after file change' })
        }
    }

    private clearActionReloadTimeout() {
        if (this.actionReloadTimeout === null) return

        window.clearTimeout(this.actionReloadTimeout)
        this.actionReloadTimeout = null
    }

    private scheduleMarkdownReload(event: ProjectWatchEvent) {
        const pendingRemovalTimeout = this.markdownRemovalTimeoutsByPath.get(event.path)
        if (pendingRemovalTimeout !== undefined) {
            window.clearTimeout(pendingRemovalTimeout)
            this.markdownRemovalTimeoutsByPath.delete(event.path)
        }

        if (event.changeKind === 'removed') {
            const timeout = window.setTimeout(() => {
                this.markdownRemovalTimeoutsByPath.delete(event.path)
                this.markdownReloadEventsByPath.set(event.path, event)
                this.scheduleMarkdownReloadBatch()
            }, MARKDOWN_REMOVAL_GRACE_MS)
            this.markdownRemovalTimeoutsByPath.set(event.path, timeout)
            return
        }

        this.markdownReloadEventsByPath.set(event.path, event)
        this.scheduleMarkdownReloadBatch()
    }

    private scheduleMarkdownReloadBatch() {
        this.clearMarkdownReloadTimeout()
        this.markdownReloadTimeout = window.setTimeout(() => {
            void this.reloadMarkdownFilesFromWatchEvents()
        }, MARKDOWN_RELOAD_DEBOUNCE_MS)
    }

    private clearMarkdownReloadTimeout() {
        if (this.markdownReloadTimeout === null) return

        window.clearTimeout(this.markdownReloadTimeout)
        this.markdownReloadTimeout = null
    }

    private clearMarkdownRemovalTimeouts() {
        this.markdownRemovalTimeoutsByPath.forEach((timeout) => window.clearTimeout(timeout))
        this.markdownRemovalTimeoutsByPath.clear()
    }

    private async reloadMarkdownFilesFromWatchEvents() {
        const { commitBatcher, storage } = this.dependencies.requireDependencies()
        const currentProject = this.dependencies.project()
        if (!currentProject || !storage.loadFile) return

        this.clearMarkdownReloadTimeout()
        const events = [...this.markdownReloadEventsByPath.values()]
        this.markdownReloadEventsByPath.clear()
        const updatedFiles: MarkdownFile[] = []
        const removedPaths: string[] = []

        for (const event of events) {
            if (this.dependencies.commitPathsInFlight().has(event.path)) continue
            const loadedFile = event.changeKind === 'removed' ? null : await this.loadWatchedMarkdownFile(event)
            if (loadedFile && this.dependencies.matchesCurrentContent(loadedFile.path, loadedFile.content)) continue
            const dirtyOpenDocument = openFilesService.getRegisteredDocuments().some((document) => (
                document.kind === 'card' && document.path === event.path && document.dirty
            ))
            if (commitBatcher.hasPendingFile(event.path) || dirtyOpenDocument) {
                reportMarkdownWatchConflict(event.path)
                continue
            }

            if (event.changeKind === 'removed') {
                removedPaths.push(event.path)
                continue
            }

            if (!loadedFile) {
                if (event.changeKind === 'unknown') removedPaths.push(event.path)
                continue
            }

            const currentFile = this.dependencies.files().find((file) => file.path === loadedFile.path)
            if (currentFile?.content === loadedFile.content) continue

            updatedFiles.push(loadedFile)
        }

        const removedPathSet = new Set(removedPaths)
        const watchedFiles = mergeFiles(
            this.dependencies.files().filter((file) => !removedPathSet.has(file.path)),
            updatedFiles,
        )
        const importedFiles = await this.importExternalCardFiles(watchedFiles, this.dependencies.requireDependencies().config.workingFolder)
        if (updatedFiles.length === 0 && removedPaths.length === 0 && importedFiles === watchedFiles) return

        const { config } = this.dependencies.requireDependencies()
        const currentFiles = this.dependencies.files()
        const currentFilesByPath = new Map(currentFiles.map((file) => [file.path, file]))
        const importedPaths = new Set(importedFiles.map((file) => file.path))
        const changedFiles = importedFiles.filter((file) => {
            const currentFile = currentFilesByPath.get(file.path)
            return !currentFile || currentFile.content !== file.content || currentFile.sha !== file.sha
        })
        const deletedPaths = currentFiles.filter((file) => !importedPaths.has(file.path)).map((file) => file.path)
        this.dependencies.updateFiles(changedFiles, deletedPaths, config.workingFolder)
        await this.ensureCardInternalIds()
        await this.dependencies.migrateAgentLogReferences()
        this.dependencies.dispatchChanged()
    }

    private async ensureCardInternalIds() {
        if (projectAccessService.getSnapshot()) return

        await this.dependencies.ensureCardInternalIds()
    }

    private async loadWatchedMarkdownFile(event: ProjectWatchEvent) {
        const { storage } = this.dependencies.requireDependencies()
        const currentProject = this.dependencies.project()
        if (!currentProject || !storage.loadFile) return null

        try {
            return await storage.loadFile(currentProject, event.path)
        } catch (error) {
            if (event.changeKind === 'unknown' || event.changeKind === 'removed') return null

            console.error('Failed to load watched markdown file', error)

            return null
        }
    }

    private async reloadActionsFromCurrentProject() {
        const { config, storage } = this.dependencies.requireDependencies()
        const currentProject = this.dependencies.project()
        if (!currentProject) return

        const changes = [...this.actionReloadChangesByPath.values()]
        if (changes.length === 0) return

        this.clearActionReloadTimeout()
        this.actionReloadChangesByPath.clear()
        const actionFiles = await storage.loadActionFiles(currentProject, config.actionsFolder)
        actionService.reloadFromFiles(actionFiles, changes)
        reportActionLoadIssues()
    }
}

const fs = require('node:fs/promises');
const path = require('node:path');

const { ensureInsideRoot } = require('../../git/git_commands');

const CSV_COLUMNS = [
    'recorded_at',
    'record_type',
    'provider',
    'limit_id',
    'window_id',
    'window_duration_minutes',
    'resets_at',
    'input_tokens',
    'cached_input_tokens',
    'output_tokens',
    'reasoning_tokens',
    'total_tokens',
    'used_percent',
    'used_percent_delta',
];
const CSV_HEADER = CSV_COLUMNS.join(',');
const DEFAULT_LIMIT_ID = 'default';
const SUPPORTED_PROVIDERS = new Set(['claude', 'codex']);
const UNIX_MILLISECONDS_THRESHOLD = 1_000_000_000_000;
const USAGE_METRICS_FILE = 'usage_metrics.csv';
const CLAUDE_WINDOW_DURATIONS = new Map([
    ['five_hour', 300],
    ['weekly', 10_080],
]);

function csvValue(value) {
    const text = value === null || value === undefined ? '' : String(value);
    if (!/[",\r\n]/u.test(text)) return text;

    return `"${text.replaceAll('"', '""')}"`;
}

function csvRow(record) {
    return CSV_COLUMNS.map((column) => csvValue(record[column])).join(',');
}

function completeCsvRecord(values) {
    return Object.fromEntries(CSV_COLUMNS.map((column) => [column, values[column] ?? '']));
}

function finishCsvRecord(records, fields, field, valid) {
    records.push({ fields: [...fields, field], valid });
}

/** Parses RFC 4180 records while retaining row validity so malformed history can be skipped. */
function parseCsv(content) {
    const records = [];
    let fields = [];
    let field = '';
    let inQuotes = false;
    let afterQuote = false;
    let valid = true;
    for (let index = 0; index < content.length; index += 1) {
        const character = content[index];
        if (inQuotes) {
            if (character !== '"') {
                field += character;
                continue;
            }
            if (content[index + 1] === '"') {
                field += '"';
                index += 1;
                continue;
            }
            inQuotes = false;
            afterQuote = true;
            continue;
        }
        if (afterQuote) {
            if (character === ',') {
                fields.push(field);
                field = '';
                afterQuote = false;
                continue;
            }
            if (character === '\r' || character === '\n') {
                finishCsvRecord(records, fields, field, valid);
                if (character === '\r' && content[index + 1] === '\n') index += 1;
                fields = [];
                field = '';
                afterQuote = false;
                valid = true;
                continue;
            }
            valid = false;
            afterQuote = false;
        }
        if (character === '"') {
            if (field.length === 0) {
                inQuotes = true;
                continue;
            }
            valid = false;
            field += character;
            continue;
        }
        if (character === ',') {
            fields.push(field);
            field = '';
            continue;
        }
        if (character === '\r' || character === '\n') {
            finishCsvRecord(records, fields, field, valid);
            if (character === '\r' && content[index + 1] === '\n') index += 1;
            fields = [];
            field = '';
            valid = true;
            continue;
        }
        field += character;
    }
    if (inQuotes) valid = false;
    if (fields.length > 0 || field.length > 0 || afterQuote || !valid) finishCsvRecord(records, fields, field, valid);

    return records;
}

function validTimestamp(timestamp) {
    return typeof timestamp === 'number' && Number.isFinite(timestamp);
}

function isoTimestamp(timestamp) {
    if (!validTimestamp(timestamp)) return null;
    try {
        return new Date(timestamp).toISOString();
    } catch {
        return null;
    }
}

function validIsoTimestamp(value) {
    if (typeof value !== 'string') return false;

    return isoTimestamp(Date.parse(value)) === value;
}

function resetTimestampMilliseconds(provider, resetTimestamp) {
    if (!validTimestamp(resetTimestamp)) return null;
    if (provider === 'codex' && resetTimestamp < UNIX_MILLISECONDS_THRESHOLD) return resetTimestamp * 1000;

    return resetTimestamp;
}

function validTokenCount(value) {
    return Number.isSafeInteger(value) && value >= 0;
}

function normalizeTokenUsage(usage) {
    if (!usage || typeof usage !== 'object' || Array.isArray(usage)) return null;
    const values = {
        cachedInputTokens: usage.cachedInputTokens,
        inputTokens: usage.inputTokens,
        outputTokens: usage.outputTokens,
        reasoningTokens: usage.reasoningTokens,
        totalTokens: usage.totalTokens,
    };
    if (!Object.values(values).every(validTokenCount)) return null;
    const calculatedTotal = values.inputTokens + values.cachedInputTokens + values.outputTokens + values.reasoningTokens;
    if (values.totalTokens !== calculatedTotal) return null;

    return values;
}

function accountKey(provider, limitId, windowId) {
    return `${provider}\u0000${limitId}\u0000${windowId}`;
}

function normalizeAccountWindow(provider, limitId, windowId, windowDurationMinutes, window) {
    if (!window || typeof window !== 'object' || Array.isArray(window)) return null;
    if (typeof limitId !== 'string' || limitId.length === 0) return null;
    if (typeof windowId !== 'string' || windowId.length === 0) return null;
    if (!validTimestamp(window.resetsAt)) return null;
    if (!Number.isFinite(window.usedPercent) || window.usedPercent < 0 || window.usedPercent > 100) return null;
    if (!Number.isFinite(windowDurationMinutes) || windowDurationMinutes <= 0) return null;
    const resetTime = isoTimestamp(resetTimestampMilliseconds(provider, window.resetsAt));
    if (!resetTime) return null;

    return {
        limitId,
        resetsAt: resetTime,
        usedPercent: window.usedPercent,
        windowDurationMinutes,
        windowId,
    };
}

function codexAccountWindows(snapshot) {
    if (!Array.isArray(snapshot.buckets)) return null;
    const windows = [];
    for (const bucket of snapshot.buckets) {
        if (!bucket || typeof bucket !== 'object' || Array.isArray(bucket)) return null;
        if (typeof bucket.limitId !== 'string' || bucket.limitId.length === 0) return null;
        for (const windowId of ['primary', 'secondary']) {
            const window = bucket[windowId];
            if (window === null || window === undefined) continue;
            const normalized = normalizeAccountWindow(
                'codex',
                bucket.limitId,
                windowId,
                window.windowDurationMins,
                window,
            );
            if (!normalized) return null;
            windows.push(normalized);
        }
    }

    return windows;
}

function claudeAccountWindows(snapshot) {
    if (!Array.isArray(snapshot.windows)) return null;
    const windows = [];
    for (const window of snapshot.windows) {
        const windowDurationMinutes = CLAUDE_WINDOW_DURATIONS.get(window?.id);
        if (!windowDurationMinutes) return null;
        const normalized = normalizeAccountWindow(
            'claude',
            DEFAULT_LIMIT_ID,
            window.id,
            windowDurationMinutes,
            window,
        );
        if (!normalized) return null;
        windows.push(normalized);
    }

    return windows;
}

function normalizeAccountSnapshot(provider, snapshot) {
    if (!SUPPORTED_PROVIDERS.has(provider)) return null;
    if (!snapshot || typeof snapshot !== 'object' || Array.isArray(snapshot)) return null;
    if (snapshot.available !== true || !validTimestamp(snapshot.observedAt)) return null;
    const recordedAt = isoTimestamp(snapshot.observedAt);
    if (!recordedAt) return null;
    const windows = provider === 'codex' ? codexAccountWindows(snapshot) : claudeAccountWindows(snapshot);
    if (!windows || windows.length === 0) return null;
    if (new Set(windows.map(({ limitId, windowId }) => accountKey(provider, limitId, windowId))).size !== windows.length) return null;

    return { recordedAt, windows };
}

function tokenRecord(provider, usage, recordedAt) {
    return completeCsvRecord({
        cached_input_tokens: usage.cachedInputTokens,
        input_tokens: usage.inputTokens,
        output_tokens: usage.outputTokens,
        provider,
        reasoning_tokens: usage.reasoningTokens,
        recorded_at: recordedAt,
        record_type: 'token_usage',
        total_tokens: usage.totalTokens,
    });
}

function accountRecord(provider, window, recordedAt, delta) {
    return completeCsvRecord({
        limit_id: window.limitId,
        provider,
        recorded_at: recordedAt,
        record_type: 'account_usage',
        resets_at: window.resetsAt,
        used_percent: window.usedPercent,
        used_percent_delta: delta,
        window_duration_minutes: window.windowDurationMinutes,
        window_id: window.windowId,
    });
}

function validRestoredAccountRecord(record) {
    if (record.length !== CSV_COLUMNS.length) return false;
    const values = Object.fromEntries(CSV_COLUMNS.map((column, index) => [column, record[index]]));
    if (values.record_type !== 'account_usage' || !SUPPORTED_PROVIDERS.has(values.provider)) return false;
    if (!values.limit_id || !values.window_id || !validIsoTimestamp(values.recorded_at)) return false;
    if (!validIsoTimestamp(values.resets_at) || !Number.isFinite(Number(values.used_percent))) return false;
    if (!Number.isFinite(Number(values.window_duration_minutes)) || Number(values.window_duration_minutes) <= 0) return false;
    if (values.used_percent_delta !== '' && !Number.isFinite(Number(values.used_percent_delta))) return false;
    const tokenColumns = ['input_tokens', 'cached_input_tokens', 'output_tokens', 'reasoning_tokens', 'total_tokens'];

    return tokenColumns.every((column) => values[column] === '');
}

function restoreBaselines(content) {
    const records = parseCsv(content);
    if (records.length === 0 || !records[0].valid || records[0].fields.join(',') !== CSV_HEADER) return new Map();
    const baselines = new Map();
    for (const { fields, valid } of records.slice(1)) {
        if (!valid || !validRestoredAccountRecord(fields)) continue;
        const values = Object.fromEntries(CSV_COLUMNS.map((column, index) => [column, fields[index]]));
        const key = accountKey(values.provider, values.limit_id, values.window_id);
        baselines.set(key, { resetsAt: values.resets_at, usedPercent: Number(values.used_percent) });
    }

    return baselines;
}

function usageMetricsPath(project, projectFolder) {
    if (!project || typeof project !== 'object' || Array.isArray(project)) return null;
    const { rootPath } = project;
    if (typeof rootPath !== 'string' || rootPath.length === 0) return null;
    if (typeof projectFolder !== 'string') return null;
    let projectFolderPath;
    try {
        projectFolderPath = ensureInsideRoot(rootPath, path.resolve(rootPath, projectFolder));
    } catch {
        return null;
    }

    return ensureInsideRoot(rootPath, path.join(projectFolderPath, USAGE_METRICS_FILE));
}

/** Owns append-only project usage metrics, per-file ordering, and persisted account baselines. */
class UsageMetricsService {
    constructor(dependencies = {}) {
        this.appendFile = dependencies.appendFile ?? fs.appendFile;
        this.errorReporter = dependencies.errorReporter ?? (() => undefined);
        this.readFile = dependencies.readFile ?? fs.readFile;
        this.fileStates = new Map();
        this.fileWrites = new Map();
        this.filePath = null;
    }

    /** Binds metrics storage to the one active primary project. */
    startProject(project, projectFolder) {
        const filePath = usageMetricsPath(project, projectFolder);
        if (!filePath) throw new Error('Invalid usage metrics project');
        this.filePath = filePath;
    }

    requireFilePath() {
        if (!this.filePath) throw new Error('Usage metrics project is not active');

        return this.filePath;
    }

    async recordTokenUsage(provider, usageValue, recordedAtValue) {
        const filePath = this.requireFilePath();
        const usage = normalizeTokenUsage(usageValue);
        const recordedAt = isoTimestamp(recordedAtValue);
        if (!SUPPORTED_PROVIDERS.has(provider) || !usage || !recordedAt) return false;

        return this.runNonFatal(filePath, async () => {
            const state = await this.loadFileState(filePath);
            await this.appendRecords(filePath, state, [tokenRecord(provider, usage, recordedAt)]);

            return true;
        });
    }

    async recordAccountUsage(provider, snapshotValue) {
        const filePath = this.requireFilePath();
        const snapshot = normalizeAccountSnapshot(provider, snapshotValue);
        if (!snapshot) return false;

        return this.runNonFatal(filePath, async () => {
            const state = await this.loadFileState(filePath);
            const changed = snapshot.windows.filter((window) => {
                const baseline = state.baselines.get(accountKey(provider, window.limitId, window.windowId));

                return !baseline || baseline.usedPercent !== window.usedPercent || baseline.resetsAt !== window.resetsAt;
            });
            if (changed.length === 0) return false;
            const records = changed.map((window) => {
                const baseline = state.baselines.get(accountKey(provider, window.limitId, window.windowId));
                const delta = !baseline ? '' : baseline.resetsAt === window.resetsAt
                    ? window.usedPercent - baseline.usedPercent
                    : window.usedPercent;

                return accountRecord(provider, window, snapshot.recordedAt, delta);
            });
            await this.appendRecords(filePath, state, records);
            changed.forEach((window) => {
                const key = accountKey(provider, window.limitId, window.windowId);
                state.baselines.set(key, { resetsAt: window.resetsAt, usedPercent: window.usedPercent });
            });

            return true;
        });
    }

    async runNonFatal(filePath, operation) {
        try {
            return await this.enqueue(filePath, operation);
        } catch (error) {
            try {
                await this.errorReporter(error);
            } catch {
                // Metrics and metrics error reporting must not affect agent runs.
            }

            return false;
        }
    }

    enqueue(filePath, operation) {
        const previous = this.fileWrites.get(filePath) ?? Promise.resolve();
        const write = previous.catch(() => undefined).then(operation);
        this.fileWrites.set(filePath, write);
        const clear = () => {
            if (this.fileWrites.get(filePath) === write) this.fileWrites.delete(filePath);
        };
        void write.then(clear, clear);

        return write;
    }

    async loadFileState(filePath) {
        const current = this.fileStates.get(filePath);
        if (current) return current;
        let content = '';
        try {
            content = await this.readFile(filePath, 'utf8');
        } catch (error) {
            if (error?.code !== 'ENOENT') throw error;
        }
        const state = {
            baselines: restoreBaselines(content),
            hasContent: content.length > 0,
            needsRecordSeparator: content.length > 0 && !/[\r\n]$/u.test(content),
        };
        this.fileStates.set(filePath, state);

        return state;
    }

    async appendRecords(filePath, state, records) {
        const rows = records.map(csvRow).join('\r\n');
        const header = state.hasContent ? '' : `${CSV_HEADER}\r\n`;
        const recordSeparator = state.needsRecordSeparator ? '\r\n' : '';
        const content = `${recordSeparator}${header}${rows}\r\n`;
        await this.appendFile(filePath, content, 'utf8');
        state.hasContent = true;
        state.needsRecordSeparator = false;
    }
}

module.exports = {
    CSV_COLUMNS,
    CSV_HEADER,
    UsageMetricsService,
    parseCsv,
};

const crypto = require('node:crypto');
const fs = require('node:fs');
const path = require('node:path');

const {
    createActivityFile,
    findActivityConversation,
    parseActivityValue,
} = require('../../../../shared/card_activity.mjs');
const {
    activityFilePath,
    conversationActivityReference,
    parseConversationActivityReference,
} = require('../../../../shared/activity_paths.mjs');
const {
    assertGitRoot,
    commitExists,
    commitTrackedPaths,
    ensureInsideRoot,
    isCommitAncestor,
    pathExists,
    requireRootPath,
} = require('../../git/git_commands');

const activityWriteQueues = new Map();
const unwrittenActivityValues = new Map();
const ACTIVITY_RENAME_RETRY_DELAYS_MS = [25, 50, 100, 200];
const RETRYABLE_RENAME_ERROR_CODES = new Set(['EACCES', 'EBUSY', 'EPERM']);
const VISIBILITY_CHECK_CONCURRENCY = 8;

function requireProjectFolder(value) {
    if (typeof value !== 'string') throw new Error('Missing activity projectFolder');

    return value;
}

function requireOrigin(value) {
    return createActivityFile(value).origin;
}

function resolveActivityPath(rootPath, projectFolder, origin) {
    const relativePath = activityFilePath(requireProjectFolder(projectFolder), requireOrigin(origin));

    return {
        absolutePath: ensureInsideRoot(rootPath, path.join(rootPath, relativePath)),
        relativePath,
    };
}

async function readStoredActivity(filePath) {
    const unwritten = unwrittenActivityValues.get(filePath);
    if (unwritten) return { value: unwritten };
    if (!await pathExists(filePath)) return { value: null };
    const value = JSON.parse(await fs.promises.readFile(filePath, 'utf8'));

    return { value };
}

function activityValue(stored, origin) {
    return stored.value === null ? createActivityFile(origin) : parseActivityValue(stored.value, origin);
}

async function loadActivityValue(filePath, origin) {
    return activityValue(await readStoredActivity(filePath, origin), origin);
}

async function readActivityFile(filePath, origin) {
    return activityValue(await readStoredActivity(filePath, origin), origin);
}

function delay(milliseconds) {
    return new Promise((resolve) => {
        setTimeout(resolve, milliseconds);
    });
}

async function renameActivityFile(temporaryPath, filePath) {
    for (const retryDelay of ACTIVITY_RENAME_RETRY_DELAYS_MS) {
        try {
            await fs.promises.rename(temporaryPath, filePath);

            return;
        } catch (error) {
            if (!RETRYABLE_RENAME_ERROR_CODES.has(error?.code)) throw error;
            await delay(retryDelay);
        }
    }

    await fs.promises.rename(temporaryPath, filePath);
}

async function writeActivityFile(filePath, activity) {
    const temporaryPath = `${filePath}.${crypto.randomUUID()}.tmp`;
    await fs.promises.mkdir(path.dirname(filePath), { recursive: true });
    try {
        await fs.promises.writeFile(temporaryPath, `${JSON.stringify(activity, null, 2)}\n`);
        await renameActivityFile(temporaryPath, filePath);
        unwrittenActivityValues.delete(filePath);
    } catch (error) {
        unwrittenActivityValues.set(filePath, activity);

        throw error;
    } finally {
        await fs.promises.rm(temporaryPath, { force: true });
    }
}

function queueActivityUpdate(filePath, update) {
    const previousWrite = activityWriteQueues.get(filePath) ?? Promise.resolve();
    const write = previousWrite.then(update);
    const queueTail = write.catch(() => undefined);
    activityWriteQueues.set(filePath, queueTail);
    void queueTail.finally(() => {
        if (activityWriteQueues.get(filePath) === queueTail) activityWriteQueues.delete(filePath);
    });

    return write;
}

async function updateActivity(project, projectFolder, origin, update) {
    const rootPath = requireRootPath(project);
    await assertGitRoot(rootPath);
    const { absolutePath, relativePath } = resolveActivityPath(rootPath, projectFolder, origin);
    const activity = await queueActivityUpdate(absolutePath, async () => {
        const current = await loadActivityValue(absolutePath, origin);
        const next = update(current);
        await writeActivityFile(absolutePath, next);

        return next;
    });

    return { activity, relativePath };
}

async function ensureActivityFile(project, projectFolder, origin) {
    const rootPath = requireRootPath(project);
    await assertGitRoot(rootPath);
    const { absolutePath, relativePath } = resolveActivityPath(rootPath, projectFolder, origin);
    await queueActivityUpdate(absolutePath, async () => {
        if (await pathExists(absolutePath)) return;

        await writeActivityFile(absolutePath, createActivityFile(origin));
    });

    return relativePath;
}

async function updateAndCommitActivity(project, projectFolder, origin, update, message) {
    const rootPath = requireRootPath(project);
    await assertGitRoot(rootPath);
    const { absolutePath, relativePath } = resolveActivityPath(rootPath, projectFolder, origin);

    return queueActivityUpdate(absolutePath, async () => {
        const current = await loadActivityValue(absolutePath, origin);
        const next = update(current);
        await writeActivityFile(absolutePath, next);
        const commit = await commitTrackedPaths(rootPath, [relativePath], message);

        return { activity: next, commit, relativePath };
    });
}

async function appendActionActivity(project, projectFolder, origin, record) {
    return updateActivity(project, projectFolder, origin, (activity) => ({
        ...activity,
        records: [...activity.records, record],
    }));
}

async function appendAndCommitActionActivity(project, projectFolder, origin, record, message) {
    return updateAndCommitActivity(project, projectFolder, origin, (activity) => ({
        ...activity,
        records: [...activity.records, record],
    }), message);
}

async function appendAndCommitSystemActivity(project, projectFolder, origin, record, message) {
    return updateAndCommitActivity(project, projectFolder, origin, (activity) => ({
        ...activity,
        records: [...activity.records, record],
    }), message);
}

function upsertConversation(activity, conversation) {
    if (typeof conversation.viewed !== 'boolean') throw new Error('Missing agent conversation viewed');
    const storedConversation = Object.fromEntries(Object.entries(conversation).filter(([fieldName]) => fieldName !== 'path'));

    return {
        ...activity,
        conversations: activity.conversations.some(({ id }) => id === storedConversation.id)
            ? activity.conversations.map((current) => (
                current.id === storedConversation.id ? { ...storedConversation, viewed: current.viewed } : current
            ))
            : [...activity.conversations, storedConversation],
    };
}

async function upsertActivityConversation(project, projectFolder, origin, conversation) {
    return updateActivity(project, projectFolder, origin, (activity) => upsertConversation(activity, conversation));
}

async function upsertAndCommitActivityConversation(project, projectFolder, origin, conversation, message) {
    return updateAndCommitActivity(
        project,
        projectFolder,
        origin,
        (activity) => upsertConversation(activity, conversation),
        message,
    );
}

async function updateActivityConversationViewed(project, reference, viewed) {
    if (typeof reference !== 'string' || reference.length === 0) throw new Error('Missing agent conversation reference');
    if (typeof viewed !== 'boolean') throw new Error('Invalid agent conversation viewed');

    const rootPath = requireRootPath(project);
    await assertGitRoot(rootPath);
    const { activityPath, conversationId } = parseConversationActivityReference(reference);
    const absolutePath = ensureInsideRoot(rootPath, path.join(rootPath, activityPath));

    return queueActivityUpdate(absolutePath, async () => {
        const stored = await readStoredActivity(absolutePath);
        const activity = activityValue(stored);
        const conversation = findActivityConversation(activity, conversationId);
        const updatedConversation = { ...conversation, viewed };
        const storedActivity = stored.value;
        const updatedActivity = {
            ...storedActivity,
            conversations: storedActivity.conversations.map((current) => (
                current.id === conversationId ? { ...current, viewed } : current
            )),
        };
        await writeActivityFile(absolutePath, updatedActivity);

        return { ...updatedConversation, path: reference };
    });
}

async function updateCardActionSettings(project, projectFolder, cardInternalId, actionId, settings) {
    if (typeof cardInternalId !== 'string' || cardInternalId.length === 0) throw new Error('Missing card action settings cardInternalId');
    if (typeof actionId !== 'string' || actionId.length === 0) throw new Error('Missing card action settings actionId');
    const origin = { cardInternalId, kind: 'card' };
    const validationActivity = createActivityFile(origin);
    validationActivity.actionSettings[actionId] = settings;
    const validatedSettings = parseActivityValue(validationActivity, origin).actionSettings[actionId];

    return updateActivity(project, projectFolder, origin, (activity) => ({
        ...activity,
        actionSettings: { ...activity.actionSettings, [actionId]: validatedSettings },
    }));
}

async function loadActivityConversation(project, reference) {
    const rootPath = requireRootPath(project);
    await assertGitRoot(rootPath);
    const { activityPath, conversationId } = parseConversationActivityReference(reference);
    const absolutePath = ensureInsideRoot(rootPath, path.join(rootPath, activityPath));
    const activity = await readActivityFile(absolutePath);
    const conversation = findActivityConversation(activity, conversationId);

    return { ...conversation, path: reference };
}

async function loadActivityConversations(project, activityPath) {
    if (typeof activityPath !== 'string' || activityPath.length === 0) throw new Error('Missing activity path');
    const rootPath = requireRootPath(project);
    await assertGitRoot(rootPath);
    const absolutePath = ensureInsideRoot(rootPath, path.join(rootPath, activityPath));
    const activity = await readActivityFile(absolutePath);

    return activity.conversations.map((conversation) => ({
        ...conversation,
        path: conversationActivityReference(activityPath, conversation.id),
    }));
}

async function closeWaitingActivityConversation(project, reference, status) {
    if (typeof reference !== 'string' || reference.length === 0) throw new Error('Missing agent conversation reference');
    if (status !== 'completed' && status !== 'cancelled') throw new Error(`Invalid waiting conversation terminal status: ${status}`);

    const rootPath = requireRootPath(project);
    await assertGitRoot(rootPath);
    const { activityPath, conversationId } = parseConversationActivityReference(reference);
    const absolutePath = ensureInsideRoot(rootPath, path.join(rootPath, activityPath));

    return queueActivityUpdate(absolutePath, async () => {
        const stored = await readStoredActivity(absolutePath);
        const activity = activityValue(stored);
        const conversation = findActivityConversation(activity, conversationId);
        if (conversation.status !== 'waitingForInput') {
            throw new Error(`Agent conversation is no longer waiting for input: ${reference}`);
        }

        const completedAt = new Date().toISOString();
        const storedActivity = stored.value;
        const updatedActivity = {
            ...storedActivity,
            conversations: storedActivity.conversations.map((storedConversation) => (
                storedConversation.id === conversationId
                    ? { ...storedConversation, completedAt, status, viewed: conversation.viewed }
                    : storedConversation
            )),
        };
        await writeActivityFile(absolutePath, updatedActivity);
        const updatedConversation = findActivityConversation(parseActivityValue(updatedActivity), conversationId);

        return { ...updatedConversation, path: reference };
    });
}

async function listAgentConversationReferences(project, projectFolder) {
    const rootPath = requireRootPath(project);
    await assertGitRoot(rootPath);
    const origin = { kind: 'project' };
    const { absolutePath, relativePath } = resolveActivityPath(rootPath, projectFolder, origin);
    const activity = await readActivityFile(absolutePath, origin);

    return activity.conversations.map(({ id }) => conversationActivityReference(relativePath, id));
}

async function visibleCommit(rootPath, primaryBranch, validBranches, commit) {
    const available = await commitExists(rootPath, commit.commit);
    if (!available) {
        return commit.branch === primaryBranch || validBranches.has(commit.branch)
            ? { ...commit, available: false }
            : null;
    }
    if (await isCommitAncestor(rootPath, commit.commit, `refs/heads/${primaryBranch}`)) return { ...commit, available: true };
    if (!validBranches.has(commit.branch)) return null;

    return await isCommitAncestor(rootPath, commit.commit, `refs/heads/${commit.branch}`)
        ? { ...commit, available: true }
        : null;
}

async function runVisibilityWorker(state) {
    while (state.nextIndex < state.tasks.length) {
        const taskIndex = state.nextIndex;
        state.nextIndex += 1;
        const { commit } = state.tasks[taskIndex];
        state.results[taskIndex] = await visibleCommit(state.rootPath, state.primaryBranch, state.validBranches, commit);
    }
}

async function filterVisibleCommits(rootPath, primaryBranch, validBranches, records) {
    const tasks = records.flatMap((record, recordIndex) => (
        record.commits.map((commit) => ({ commit, recordIndex }))
    ));
    const state = { nextIndex: 0, primaryBranch, results: Array(tasks.length), rootPath, tasks, validBranches };
    const workerCount = Math.min(VISIBILITY_CHECK_CONCURRENCY, tasks.length);
    await Promise.all(Array.from({ length: workerCount }, () => runVisibilityWorker(state)));
    const commitsByRecord = records.map(() => []);
    for (const [taskIndex, visible] of state.results.entries()) {
        if (!visible) continue;
        commitsByRecord[tasks[taskIndex].recordIndex].push(visible);
    }

    return records.map((record, recordIndex) => ({ ...record, commits: commitsByRecord[recordIndex] }));
}

async function loadCardActivity(project, projectFolder, cardInternalId, worktrees) {
    const rootPath = requireRootPath(project);
    await assertGitRoot(rootPath);
    if (!Array.isArray(worktrees)) throw new Error('Missing linked worktrees');
    const origin = { cardInternalId, kind: 'card' };
    const { absolutePath } = resolveActivityPath(rootPath, projectFolder, origin);
    const activity = await readActivityFile(absolutePath, origin);
    const validBranches = new Set(worktrees.filter(({ valid }) => valid).map(({ branch }) => branch));
    const records = await filterVisibleCommits(rootPath, project.branch, validBranches, activity.records);

    return { ...activity, records };
}

function activityConversationReference(projectFolder, origin, conversationId) {
    return conversationActivityReference(activityFilePath(projectFolder, origin), conversationId);
}

