    controls: INITIAL_CONTROLS,
    error: null,
    omittedTimerCount: 0,
    rows: [],
    status: 'idle',
    tokenTimeAvailable: false,
}
const METRICS_COLUMNS = [
    'recorded_at',
    'record_type',
    'provider',
    'limit_id',
    'window_id',
    'window_duration_minutes',
    'resets_at',
    'input_tokens',
    'cached_input_tokens',
    'output_tokens',
    'reasoning_tokens',
    'total_tokens',
    'used_percent',
    'used_percent_delta',
]

function normalizePath(path: string) {
    return path.replace(/\\/gu, '/').replace(/^\/+|\/+$/gu, '')
}

function joinPath(folder: string, fileName: string) {
    const normalizedFolder = normalizePath(folder)

    return normalizedFolder ? `${normalizedFolder}/${fileName}` : fileName
}

function isValidIsoTimestamp(value: string) {
    const milliseconds = Date.parse(value)

    return Number.isFinite(milliseconds) && new Date(milliseconds).toISOString() === value
}

function parseNonNegativeInteger(value: string, field: string, rowNumber: number) {
    if (!/^\d+$/u.test(value)) throw new Error(`Invalid usage metrics ${field} at row ${rowNumber}`)
    const parsed = Number(value)
    if (!Number.isSafeInteger(parsed)) throw new Error(`Invalid usage metrics ${field} at row ${rowNumber}`)

    return parsed
}

function parseCsvRecords(content: string) {
    const records: string[][] = []
    let fields: string[] = []
    let field = ''
    let inQuotes = false
    let afterQuote = false

    for (let index = 0; index < content.length; index += 1) {
        const character = content[index]
        if (inQuotes) {
            if (character !== '"') {
                field += character
                continue
            }
            if (content[index + 1] === '"') {
                field += '"'
                index += 1
                continue
            }
            inQuotes = false
            afterQuote = true
            continue
        }
        if (afterQuote) {
            if (character === ',') {
                fields.push(field)
                field = ''
                afterQuote = false
                continue
            }
            if (character === '\r' || character === '\n') {
                records.push([...fields, field])
                if (character === '\r' && content[index + 1] === '\n') index += 1
                fields = []
                field = ''
                afterQuote = false
                continue
            }
            throw new Error('Malformed usage metrics CSV')
        }
        if (character === '"') {
            if (field.length > 0) throw new Error('Malformed usage metrics CSV')
            inQuotes = true
            continue
        }
        if (character === ',') {
            fields.push(field)
            field = ''
            continue
        }
        if (character === '\r' || character === '\n') {
            records.push([...fields, field])
            if (character === '\r' && content[index + 1] === '\n') index += 1
            fields = []
            field = ''
            continue
        }
        field += character
    }
    if (inQuotes) throw new Error('Malformed usage metrics CSV')
    if (fields.length > 0 || field.length > 0 || afterQuote) records.push([...fields, field])

    return records
}

export function parseUsageMetrics(content: string): TokenUsageRow[] {
    const records = parseCsvRecords(content)
    const header = records[0]
    if (!header || header.length !== METRICS_COLUMNS.length || header.some((value, index) => value !== METRICS_COLUMNS[index])) {
        throw new Error('Invalid usage metrics CSV header')
    }

    return records.slice(1).flatMap((fields, index) => {
        const rowNumber = index + 2
        if (fields.length !== METRICS_COLUMNS.length) throw new Error(`Invalid usage metrics column count at row ${rowNumber}`)
        const record = Object.fromEntries(METRICS_COLUMNS.map((column, columnIndex) => [column, fields[columnIndex]]))
        if (!isValidIsoTimestamp(record.recorded_at)) throw new Error(`Invalid usage metrics recorded_at at row ${rowNumber}`)
        if (record.record_type === 'account_usage') return []
        if (record.record_type !== 'token_usage') throw new Error(`Invalid usage metrics record_type at row ${rowNumber}`)
        const inputTokens = parseNonNegativeInteger(record.input_tokens, 'input_tokens', rowNumber)
        const cachedInputTokens = parseNonNegativeInteger(record.cached_input_tokens, 'cached_input_tokens', rowNumber)
        const outputTokens = parseNonNegativeInteger(record.output_tokens, 'output_tokens', rowNumber)
        const reasoningTokens = parseNonNegativeInteger(record.reasoning_tokens, 'reasoning_tokens', rowNumber)
        const totalTokens = parseNonNegativeInteger(record.total_tokens, 'total_tokens', rowNumber)
        if (inputTokens + cachedInputTokens + outputTokens + reasoningTokens !== totalTokens) {
            throw new Error(`Inconsistent usage metrics total_tokens at row ${rowNumber}`)
        }

        return [{ recordedAt: record.recorded_at, totalTokens }]
    })
}

function recognizedActivityPath(path: string, config: ProjectConfig) {
    const normalizedPath = normalizePath(path)
    const activityFolder = normalizePath(projectActivityFolder(config.projectFolder))
    const activityPrefix = `${activityFolder}/`
    if (normalizedPath.startsWith(activityPrefix) && !normalizedPath.slice(activityPrefix.length).includes('/')) {
        return activityOriginFromPath(normalizedPath) ? normalizedPath : null
    }
    const releasesFolder = normalizePath(config.releasesFolder)
    const releasePrefix = `${releasesFolder}/`
    if (!normalizedPath.startsWith(releasePrefix)) return null
    const releaseParts = normalizedPath.slice(releasePrefix.length).split('/')
    if (releaseParts.length !== 2 || !/^card__[^/]+\.json$/u.test(releaseParts[1])) return null

    return activityOriginFromPath(normalizedPath) ? normalizedPath : null
}

export function findStatsSourcePaths(repositoryFiles: string[], config: ProjectConfig) {
    const activityPaths = repositoryFiles
        .map((path) => recognizedActivityPath(path, config))
        .filter((path): path is string => path !== null)
        .sort((left, right) => left.localeCompare(right))
    const usageMetricsPath = joinPath(config.projectFolder, USAGE_METRICS_FILE)

    return { activityPaths, usageMetricsPath: repositoryFiles.map(normalizePath).includes(usageMetricsPath) ? usageMetricsPath : null }
}

function utcBucketStart(timestamp: string, granularity: StatsGranularity) {
    const date = new Date(timestamp)
    date.setUTCHours(0, 0, 0, 0)
    if (granularity === 'week') date.setUTCDate(date.getUTCDate() - ((date.getUTCDay() + 6) % 7))
    if (granularity === 'month') date.setUTCDate(1)

    return date.toISOString()
}

function localBucketLabel(utcTimestamp: string) {
    return new Intl.DateTimeFormat(undefined, { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(utcTimestamp))
}

function inRange(timestamp: string, controls: StatsControls) {
    const milliseconds = Date.parse(timestamp)
    if (controls.startUtc && milliseconds < Date.parse(controls.startUtc)) return false
    if (controls.endUtc && milliseconds > Date.parse(controls.endUtc)) return false

    return true
}

function cardLabel(cardInternalId: string, cardPath: string | null, cardsById: Map<string, StatsCardDescriptor>) {
    const card = cardsById.get(cardInternalId)
    if (card) return `${card.visibleId}: ${card.title}`

    return cardPath ?? cardInternalId
}

function actionLabel(actionId: string, storedLabel: string | null) {
    return storedLabel && storedLabel !== actionId ? `${storedLabel} (${actionId})` : actionId
}

function canonicalConversations(activityFiles: CardActivityFile[]) {
    const conversations = new Map<string, TimedConversation>()
    const actionLabels = new Map<string, string>()
    for (const activity of activityFiles) {
        for (const record of activity.records) {
            if (record.type === 'system') continue
            actionLabels.set(record.rootActionId, record.rootActionLabel)
        }
        for (const conversation of activity.conversations) {
            const originIdentity = activity.origin.kind === 'card' ? `card:${activity.origin.cardInternalId}` : 'project'
            const identity = `${originIdentity}:${conversation.id}`
            if (conversations.has(identity)) continue
            const cardInternalId = conversation.cardInternalId ?? (activity.origin.kind === 'card' ? activity.origin.cardInternalId : null)
            conversations.set(identity, {
                actionId: conversation.actionId ?? null,
                actionLabel: conversation.actionId ? actionLabels.get(conversation.actionId) ?? conversation.title : null,
                cardInternalId,
                cardPath: conversation.cardPath,
                completedAt: conversation.completedAt,
                elapsedMs: conversation.timer?.elapsedMs ?? null,
                status: conversation.status,
                totalTokens: conversation.usage?.totalTokens ?? 0,
            })
        }
    }

    return [...conversations.values()]
}

function completedRecords(activityFiles: CardActivityFile[]) {
    const records = new Map<string, {
        actionId: string
        actionLabel: string
        cardInternalId: string | null
        completedAt: string
    }>()
    for (const activity of activityFiles) {
        for (const record of activity.records) {
            if (record.type === 'system' || !COMPLETED_ACTION_STATUSES.has(record.status)) continue
            const originIdentity = record.origin.kind === 'card' ? `card:${record.origin.cardInternalId}` : 'project'
            const identity = `${originIdentity}:${record.runId}`
            if (records.has(identity)) continue
            records.set(identity, {
                actionId: record.rootActionId,
                actionLabel: record.rootActionLabel,
                cardInternalId: record.origin.kind === 'card' ? record.origin.cardInternalId : null,
                completedAt: record.completedAt,
            })
        }
    }

    return [...records.values()]
}

function activityRows(source: LoadedStatsSource, controls: StatsControls): StatsChartRow[] {
    const buckets = new Map<string, { actionCount: number, cards: Set<string>, tokens: number }>()
    if (controls.activityMetric === 'tokens') {
        for (const row of source.tokenRows.filter(({ recordedAt }) => inRange(recordedAt, controls))) {
            const bucket = utcBucketStart(row.recordedAt, controls.granularity)
            const current = buckets.get(bucket) ?? { actionCount: 0, cards: new Set<string>(), tokens: 0 }
            current.tokens += row.totalTokens
            buckets.set(bucket, current)
        }
    } else {
        for (const record of completedRecords(source.activity).filter(({ completedAt }) => inRange(completedAt, controls))) {
            const bucket = utcBucketStart(record.completedAt, controls.granularity)
            const current = buckets.get(bucket) ?? { actionCount: 0, cards: new Set<string>(), tokens: 0 }
            current.actionCount += 1
            if (record.cardInternalId) current.cards.add(record.cardInternalId)
            buckets.set(bucket, current)
        }
    }
    const unit = controls.activityMetric

    return [...buckets.entries()]
        .sort(([left], [right]) => left.localeCompare(right))
        .map(([bucket, values]) => ({
            displayLabel: localBucketLabel(bucket),
            grouping: controls.granularity,
            identity: bucket,
            metric: controls.activityMetric,
            unit,
            utcBucketStart: bucket,
            value: controls.activityMetric === 'cards'
                ? values.cards.size
                : controls.activityMetric === 'actions' ? values.actionCount : values.tokens,
        }))
}

function totalsRows(source: LoadedStatsSource, controls: StatsControls): StatsChartRow[] {
    const cardsById = new Map(source.cards.map((card) => [card.internalId, card]))
    const totals = new Map<string, { label: string, value: number }>()
    const conversations = canonicalConversations(source.activity).filter((conversation) => {
        if (controls.totalsMetric === 'duration') {
            return TERMINAL_CONVERSATION_STATUSES.has(conversation.status)
                && conversation.completedAt !== null
                && inRange(conversation.completedAt, controls)
        }
        if (!controls.startUtc && !controls.endUtc) return true

        return conversation.completedAt !== null && inRange(conversation.completedAt, controls)
    })
    for (const conversation of conversations) {
        const identity = controls.totalsGrouping === 'card' ? conversation.cardInternalId : conversation.actionId
        if (!identity) continue
        const label = controls.totalsGrouping === 'card'
            ? cardLabel(identity, conversation.cardPath, cardsById)
            : actionLabel(identity, conversation.actionLabel)
        const value = controls.totalsMetric === 'duration' ? conversation.elapsedMs : conversation.totalTokens
        if (value === null) continue
        const current = totals.get(identity)
        totals.set(identity, { label, value: (current?.value ?? 0) + value })
    }
    const unit = controls.totalsMetric === 'duration' ? 'milliseconds' : 'tokens'

    return [...totals.entries()]
        .map(([identity, { label, value }]) => ({
            displayLabel: label,
            grouping: controls.totalsGrouping,
            identity,
            metric: controls.totalsMetric,
            unit,
            utcBucketStart: null,
            value,
        } as StatsChartRow))
        .sort((left, right) => right.value - left.value || left.displayLabel.localeCompare(right.displayLabel))
}

function buildSnapshot(source: LoadedStatsSource, controls: StatsControls): ProjectStatsSnapshot {
    const filteredConversations = canonicalConversations(source.activity).filter((conversation) => (
        TERMINAL_CONVERSATION_STATUSES.has(conversation.status)
        && conversation.completedAt !== null
        && inRange(conversation.completedAt, controls)
    ))
    const omittedTimerCount = filteredConversations.filter(({ elapsedMs }) => elapsedMs === null).length
    const rows = controls.dataset === 'activityOverTime' ? activityRows(source, controls) : totalsRows(source, controls)

    return { controls, error: null, omittedTimerCount, rows, status: 'ready', tokenTimeAvailable: source.tokenTimeAvailable }
}

function validateRangeTimestamp(value: string | null, field: string) {
    if (value !== null && !isValidIsoTimestamp(value)) throw new Error(`Invalid stats ${field}`)
}

export class ProjectStatsService extends EventTarget {
    private loadRevision = 0
    private loadedRequest: StatsOpenRequest | null = null
    private projectKey: string | null = null
    private repositoryEvents: EventTarget | null = null
    private snapshot = INITIAL_SNAPSHOT
    private source: LoadedStatsSource | null = null

    getSnapshot = () => this.snapshot

    subscribe = (listener: () => void) => {
        this.addEventListener('changed', listener)

        return () => this.removeEventListener('changed', listener)
    }

    initialize(repositoryEvents: EventTarget) {
        if (this.repositoryEvents === repositoryEvents) return
        this.repositoryEvents?.removeEventListener('repositoryChanged', this.handleRepositoryChanged)
        this.repositoryEvents = repositoryEvents
        this.repositoryEvents.addEventListener('repositoryChanged', this.handleRepositoryChanged)
    }

    async open(request: StatsOpenRequest) {
        this.syncProject(request.project)
        this.loadedRequest = request
        await this.load(request)
    }

    syncProject(project: ProjectReference | null) {
        const projectKey = project ? `${project.id}:${project.branch}` : null
        if (projectKey === this.projectKey) return

        this.projectKey = projectKey
        this.loadRevision += 1
        this.loadedRequest = null
        this.source = null
        this.publish({ ...INITIAL_SNAPSHOT, controls: this.snapshot.controls })
    }

    setControls(changes: Partial<StatsControls>) {
        const controls = { ...this.snapshot.controls, ...changes }
        validateRangeTimestamp(controls.startUtc, 'startUtc')
        validateRangeTimestamp(controls.endUtc, 'endUtc')
        if (controls.startUtc && controls.endUtc && Date.parse(controls.startUtc) > Date.parse(controls.endUtc)) {
            throw new Error('Stats start date must not be after end date')
        }
        if (!this.source) {
            this.publish({ ...this.snapshot, controls })
            return
        }

        this.publish(buildSnapshot(this.source, controls))
    }

    private readonly handleRepositoryChanged = (event: Event) => {
        const request = this.loadedRequest
        if (!request) return
        const path = normalizePath((event as CustomEvent<ProjectWatchEvent>).detail.path)
        const usageMetricsPath = joinPath(request.config.projectFolder, USAGE_METRICS_FILE)
        if (path !== usageMetricsPath && !recognizedActivityPath(path, request.config)) return

        void this.load(request)
    }

    private async load(request: StatsOpenRequest) {
        const revision = ++this.loadRevision
        this.publish({ ...this.snapshot, error: null, rows: [], status: 'loading' })
        try {
            const repositoryFiles = await request.storage.listRepositoryFiles(request.project)
            if (revision !== this.loadRevision || request !== this.loadedRequest) return
            if (!request.storage.loadTextFile) throw new Error('Repository text file loading is not available')
            const { activityPaths, usageMetricsPath } = findStatsSourcePaths(repositoryFiles, request.config)
            const activityFiles = await Promise.all(activityPaths.map(async (path) => {
                const file = await request.storage.loadTextFile?.(request.project, path)
                if (!file) throw new Error(`Activity file could not be loaded: ${path}`)
                const origin = activityOriginFromPath(path)
                if (!origin) throw new Error(`Invalid activity path: ${path}`)

                return parseActivityFile(file.content, origin)
            }))
            const metricsFile = usageMetricsPath
                ? await request.storage.loadTextFile(request.project, usageMetricsPath)
                : null
            const tokenRows = metricsFile ? parseUsageMetrics(metricsFile.content) : []
            if (revision !== this.loadRevision || request !== this.loadedRequest) return

            this.source = { activity: activityFiles, cards: request.cards, tokenRows, tokenTimeAvailable: metricsFile !== null }
            this.publish(buildSnapshot(this.source, this.snapshot.controls))
        } catch (error) {
            if (revision !== this.loadRevision || request !== this.loadedRequest) return
            const normalizedError = error instanceof Error ? error : new Error(String(error))
            this.source = null
            this.publish({ ...this.snapshot, error: normalizedError, rows: [], status: 'error' })
        }
    }

    private publish(snapshot: ProjectStatsSnapshot) {
        this.snapshot = snapshot
        this.dispatchEvent(new Event('changed'))
    }
}

export const projectStatsService = register('projectStatsService', new ProjectStatsService())

import { Box, CircularProgress, Paper, Stack, Typography } from '@mui/material'
import { useEffect, useRef, useSyncExternalStore } from 'react'
import { dialogService } from '../../services/dialog_service'
import { projectStatsService } from '../../services/stats/project_stats_service'
import { StatsBarChart } from './stats_bar_chart'
import { StatsControls } from './stats_controls'

/** Smallest stats-data subscriber; renders chart states and reports new load failures. */
export function StatsContent() {
    const snapshot = useSyncExternalStore(projectStatsService.subscribe, projectStatsService.getSnapshot, projectStatsService.getSnapshot)
    const reportedErrorRef = useRef<Error | null>(null)

    useEffect(() => {
        if (!snapshot.error || reportedErrorRef.current === snapshot.error) return
        reportedErrorRef.current = snapshot.error
        dialogService.error(snapshot.error, { fallbackMessage: 'Project stats could not be loaded' })
    }, [snapshot.error])

    if (snapshot.status === 'loading') {
        return <Stack aria-label="Loading project stats" sx={{ alignItems: 'center', flex: 1, justifyContent: 'center' }}><CircularProgress /></Stack>
    }
    if (snapshot.status === 'error') {
        return (
            <Stack role="alert" sx={{ alignItems: 'center', flex: 1, justifyContent: 'center', p: 3, textAlign: 'center' }}>
                <Typography variant="h6">Stats unavailable</Typography>
                <Typography color="text.secondary" variant="body2">{snapshot.error?.message}</Typography>
            </Stack>
        )
    }

    const tokenMetricUnavailable = snapshot.controls.dataset === 'activityOverTime'
        && snapshot.controls.activityMetric === 'tokens'
        && !snapshot.tokenTimeAvailable

    return (
        <Stack sx={{ flex: 1, minHeight: 0, p: 2.5 }} spacing={2}>
            <Typography component="h2" variant="h6">Project stats</Typography>
            <StatsControls snapshot={snapshot} />
            {snapshot.omittedTimerCount > 0 && snapshot.controls.dataset === 'totals' && snapshot.controls.totalsMetric === 'duration' ? (
                <Typography color="text.secondary" variant="body2">
                    {snapshot.omittedTimerCount} terminal conversation{snapshot.omittedTimerCount === 1 ? '' : 's'} omitted because stored timer is unavailable.
                </Typography>
            ) : null}
            <Paper
                elevation={0}
                sx={{ border: 1, borderColor: 'divider', borderRadius: 2, display: 'flex', flex: 1, minHeight: 0, overflow: 'hidden' }}
            >
                {tokenMetricUnavailable ? (
                    <Box sx={{ alignContent: 'center', flex: 1, p: 3, textAlign: 'center' }}>
                        <Typography color="text.secondary">Token usage over time unavailable: usage_metrics.csv is missing.</Typography>
                    </Box>
                ) : snapshot.rows.length === 0 ? (
                    <Box sx={{ alignContent: 'center', border: '1.5px dashed', borderColor: 'custom.borderStrong', borderRadius: 1, flex: 1, m: 2, p: 3, textAlign: 'center' }}>
                        <Typography color="custom.text4">No stats data matches current filters.</Typography>
                    </Box>
                ) : <StatsBarChart rows={snapshot.rows} />}
            </Paper>
        </Stack>
    )
}

import { Box } from '@mui/material'
import { useEffect, useMemo } from 'react'
import { dataService } from '../../services/data/data_service'
import { projectStatsService, type StatsCardDescriptor } from '../../services/stats/project_stats_service'
import { useProjectConfig } from '../hooks/use_project_config'
import { useProjectState } from '../hooks/use_project_state'
import { useWorkspaceView } from '../hooks/use_workspace_view'
import { StatsContent } from './stats_content'

/** Lifetime-stable stats surface; repository reads begin only when stats mode becomes visible. */
export function StatsView() {
    const { project, snapshot } = useProjectState()
    const config = useProjectConfig()
    const { viewMode } = useWorkspaceView()
    const cards = useMemo(() => {
        const projectCards = [...(snapshot?.activeCards ?? []), ...(snapshot?.backgroundCards ?? [])]

        return projectCards.flatMap((card): StatsCardDescriptor[] => card.header.internalId ? [{
            internalId: card.header.internalId,
            path: card.path,
            title: card.header.title,
            visibleId: card.header.id,
        }] : [])
    }, [snapshot])

    useEffect(() => {
        projectStatsService.initialize(dataService)
    }, [])

    useEffect(() => {
        projectStatsService.syncProject(project)
    }, [project])

    useEffect(() => {
        if (viewMode !== 'stats' || !project || !config) return
        const storage = dataService.getStorageService()
        if (!storage) return

        void projectStatsService.open({ cards, config, project, storage })
    }, [cards, config, project, viewMode])

    return (
        <Box
            aria-label="Stats view"
            sx={{ bgcolor: 'background.default', display: viewMode === 'stats' ? 'flex' : 'none', flex: 1, minHeight: 0, overflow: 'hidden' }}
        >
            <StatsContent />
        </Box>
    )
}

import { Box, Button, MenuItem, Select, TextField, Typography } from '@mui/material'
import type { ChangeEvent } from 'react'
import type { SelectChangeEvent } from '@mui/material'
import { dialogService } from '../../services/dialog_service'
import { projectStatsService, type ProjectStatsSnapshot } from '../../services/stats/project_stats_service'
import { downloadStatsCsv } from './stats_csv'

interface StatsControlsProps {
    snapshot: ProjectStatsSnapshot
}

function localDateTimeValue(isoTimestamp: string | null) {
    if (!isoTimestamp) return ''
    const date = new Date(isoTimestamp)
    const localMilliseconds = date.getTime() - date.getTimezoneOffset() * 60_000

    return new Date(localMilliseconds).toISOString().slice(0, 16)
}

function isoTimestampFromInput(value: string) {
    return value ? new Date(value).toISOString() : null
}

function setStatsControls(changes: Parameters<typeof projectStatsService.setControls>[0]) {
    try {
        projectStatsService.setControls(changes)
    } catch (error) {
        dialogService.error(error, { fallbackMessage: 'Stats filters could not be updated' })
    }
}

/** Service-backed chart and range controls. */
export function StatsControls({ snapshot }: StatsControlsProps) {
    const { controls, rows } = snapshot
    const handleDatasetChange = (event: SelectChangeEvent) => {
        setStatsControls({ dataset: event.target.value as typeof controls.dataset })
    }
    const handleActivityMetricChange = (event: SelectChangeEvent) => {
        setStatsControls({ activityMetric: event.target.value as typeof controls.activityMetric })
    }
    const handleGranularityChange = (event: SelectChangeEvent) => {
        setStatsControls({ granularity: event.target.value as typeof controls.granularity })
    }
    const handleTotalsGroupingChange = (event: SelectChangeEvent) => {
        setStatsControls({ totalsGrouping: event.target.value as typeof controls.totalsGrouping })
    }
    const handleTotalsMetricChange = (event: SelectChangeEvent) => {
        setStatsControls({ totalsMetric: event.target.value as typeof controls.totalsMetric })
    }
    const handleStartChange = (event: ChangeEvent<HTMLInputElement>) => {
        setStatsControls({ startUtc: isoTimestampFromInput(event.target.value) })
    }
    const handleEndChange = (event: ChangeEvent<HTMLInputElement>) => {
        setStatsControls({ endUtc: isoTimestampFromInput(event.target.value) })
    }
    const handleExport = () => downloadStatsCsv(controls.dataset, rows)

    return (
        <Box sx={{ alignItems: 'flex-end', display: 'flex', flexWrap: 'wrap', gap: 1.5 }}>
            <Box>
                <Typography color="text.secondary" variant="caption">Dataset</Typography>
                <Select aria-label="Dataset" onChange={handleDatasetChange} size="small" value={controls.dataset}>
                    <MenuItem value="activityOverTime">Activity over time</MenuItem>
                    <MenuItem value="totals">Totals by Card/Action</MenuItem>
                </Select>
            </Box>
            {controls.dataset === 'activityOverTime' ? (
                <>
                    <Box>
                        <Typography color="text.secondary" variant="caption">Metric</Typography>
                        <Select aria-label="Activity metric" onChange={handleActivityMetricChange} size="small" value={controls.activityMetric}>
                            <MenuItem value="cards">Distinct cards</MenuItem>
                            <MenuItem value="actions">Completed actions</MenuItem>
                            <MenuItem disabled={!snapshot.tokenTimeAvailable} value="tokens">Token usage</MenuItem>
                        </Select>
                    </Box>
                    <Box>
                        <Typography color="text.secondary" variant="caption">Granularity</Typography>
                        <Select aria-label="Granularity" onChange={handleGranularityChange} size="small" value={controls.granularity}>
                            <MenuItem value="day">Day</MenuItem>
                            <MenuItem value="week">Week</MenuItem>
                            <MenuItem value="month">Month</MenuItem>
                        </Select>
                    </Box>
                </>
            ) : (
                <>
                    <Box>
                        <Typography color="text.secondary" variant="caption">Grouping</Typography>
                        <Select aria-label="Totals grouping" onChange={handleTotalsGroupingChange} size="small" value={controls.totalsGrouping}>
                            <MenuItem value="card">Card</MenuItem>
                            <MenuItem value="action">Action</MenuItem>
                        </Select>
                    </Box>
                    <Box>
                        <Typography color="text.secondary" variant="caption">Metric</Typography>
                        <Select aria-label="Totals metric" onChange={handleTotalsMetricChange} size="small" value={controls.totalsMetric}>
                            <MenuItem value="duration">Measured duration</MenuItem>
                            <MenuItem value="tokens">Token usage</MenuItem>
                        </Select>
                    </Box>
                </>
            )}
            <Box>
                <Typography color="text.secondary" variant="caption">From (local time)</Typography>
                <TextField
                    onChange={handleStartChange}
                    size="small"
                    slotProps={{ htmlInput: { 'aria-label': 'Range start local time' } }}
                    type="datetime-local"
                    value={localDateTimeValue(controls.startUtc)}
                />
            </Box>
            <Box>
                <Typography color="text.secondary" variant="caption">To (local time)</Typography>
                <TextField
                    onChange={handleEndChange}
                    size="small"
                    slotProps={{ htmlInput: { 'aria-label': 'Range end local time' } }}
                    type="datetime-local"
                    value={localDateTimeValue(controls.endUtc)}
                />
            </Box>
            <Button disabled={rows.length === 0} onClick={handleExport} variant="outlined">Export CSV</Button>
        </Box>
    )
}

import { activityOriginFromPath, projectActivityFolder } from '../../../../shared/activity_paths.mjs'
import { parseActivityFile, type CardActivityFile } from '../../../../shared/card_activity.mjs'
import type {
    AgentConversation,
    ProjectConfig,
    ProjectReference,
    ProjectWatchEvent,
    StorageService,
} from '../../data/data_types'
import { register } from '../service_injector'

export type StatsDataset = 'activityOverTime' | 'totals'
export type StatsGranularity = 'day' | 'week' | 'month'
export type StatsActivityMetric = 'cards' | 'actions' | 'tokens'
export type StatsTotalsGrouping = 'card' | 'action'
export type StatsTotalsMetric = 'duration' | 'tokens'
export type StatsStatus = 'idle' | 'loading' | 'ready' | 'error'

export interface StatsControls {
    activityMetric: StatsActivityMetric
    dataset: StatsDataset
    endUtc: string | null
    granularity: StatsGranularity
    startUtc: string | null
    totalsGrouping: StatsTotalsGrouping
    totalsMetric: StatsTotalsMetric
}

export interface StatsChartRow {
    displayLabel: string
    grouping: string
    identity: string
    metric: string
    unit: 'actions' | 'cards' | 'milliseconds' | 'tokens'
    utcBucketStart: string | null
    value: number
}

export interface StatsCardDescriptor {
    internalId: string
    path: string
    title: string
    visibleId: string
}

export interface ProjectStatsSnapshot {
    controls: StatsControls
    error: Error | null
    omittedTimerCount: number
    rows: StatsChartRow[]
    status: StatsStatus
    tokenTimeAvailable: boolean
}

interface LoadedStatsSource {
    activity: CardActivityFile[]
    cards: StatsCardDescriptor[]
    tokenRows: TokenUsageRow[]
    tokenTimeAvailable: boolean
}

interface StatsOpenRequest {
    cards: StatsCardDescriptor[]
    config: ProjectConfig
    project: ProjectReference
    storage: StorageService
}

interface TokenUsageRow {
    recordedAt: string
    totalTokens: number
}

interface TimedConversation {
    actionId: string | null
    actionLabel: string | null
    cardInternalId: string | null
    cardPath: string | null
    completedAt: string | null
    elapsedMs: number | null
    status: AgentConversation['status']
    totalTokens: number
}

const USAGE_METRICS_FILE = 'usage_metrics.csv'
const TERMINAL_CONVERSATION_STATUSES = new Set(['cancelled', 'completed', 'failed'])
const COMPLETED_ACTION_STATUSES = new Set(['completed', 'okButNotAfter'])
const INITIAL_CONTROLS: StatsControls = {
    activityMetric: 'actions',
    dataset: 'activityOverTime',
    endUtc: null,
    granularity: 'day',
    startUtc: null,
    totalsGrouping: 'card',
    totalsMetric: 'duration',
}
const INITIAL_SNAPSHOT: ProjectStatsSnapshot = {
    controls: INITIAL_CONTROLS,
    error: null,
    omittedTimerCount: 0,
    rows: [],
    status: 'idle',
    tokenTimeAvailable: false,
}
const METRICS_COLUMNS = [
    'recorded_at',
    'record_type',
    'provider',
    'limit_id',
    'window_id',
    'window_duration_minutes',
    'resets_at',
    'input_tokens',
    'cached_input_tokens',
    'output_tokens',
    'reasoning_tokens',
    'total_tokens',
    'used_percent',
    'used_percent_delta',
]

function normalizePath(path: string) {
    return path.replace(/\\/gu, '/').replace(/^\/+|\/+$/gu, '')
}

function joinPath(folder: string, fileName: string) {
    const normalizedFolder = normalizePath(folder)

    return normalizedFolder ? `${normalizedFolder}/${fileName}` : fileName
}

function isValidIsoTimestamp(value: string) {
    const milliseconds = Date.parse(value)

    return Number.isFinite(milliseconds) && new Date(milliseconds).toISOString() === value
}

function parseNonNegativeInteger(value: string, field: string, rowNumber: number) {
    if (!/^\d+$/u.test(value)) throw new Error(`Invalid usage metrics ${field} at row ${rowNumber}`)
    const parsed = Number(value)
    if (!Number.isSafeInteger(parsed)) throw new Error(`Invalid usage metrics ${field} at row ${rowNumber}`)

    return parsed
}

function parseCsvRecords(content: string) {
    const records: string[][] = []
    let fields: string[] = []
    let field = ''
    let inQuotes = false
    let afterQuote = false

    for (let index = 0; index < content.length; index += 1) {
        const character = content[index]
        if (inQuotes) {
            if (character !== '"') {
                field += character
                continue
            }
            if (content[index + 1] === '"') {
                field += '"'
                index += 1
                continue
            }
            inQuotes = false
            afterQuote = true
            continue
        }
        if (afterQuote) {
            if (character === ',') {
                fields.push(field)
                field = ''
                afterQuote = false
                continue
            }
            if (character === '\r' || character === '\n') {
                records.push([...fields, field])
                if (character === '\r' && content[index + 1] === '\n') index += 1
                fields = []
                field = ''
                afterQuote = false
                continue
            }
            throw new Error('Malformed usage metrics CSV')
        }
        if (character === '"') {
            if (field.length > 0) throw new Error('Malformed usage metrics CSV')
            inQuotes = true
            continue
        }
        if (character === ',') {
            fields.push(field)
            field = ''
            continue
        }
        if (character === '\r' || character === '\n') {
            records.push([...fields, field])
            if (character === '\r' && content[index + 1] === '\n') index += 1
            fields = []
            field = ''
            continue
        }
        field += character
    }
    if (inQuotes) throw new Error('Malformed usage metrics CSV')
    if (fields.length > 0 || field.length > 0 || afterQuote) records.push([...fields, field])

    return records
}

export function parseUsageMetrics(content: string): TokenUsageRow[] {
    const records = parseCsvRecords(content)
    const header = records[0]
    if (!header || header.length !== METRICS_COLUMNS.length || header.some((value, index) => value !== METRICS_COLUMNS[index])) {
        throw new Error('Invalid usage metrics CSV header')
    }

    return records.slice(1).flatMap((fields, index) => {
        const rowNumber = index + 2
        if (fields.length !== METRICS_COLUMNS.length) throw new Error(`Invalid usage metrics column count at row ${rowNumber}`)
        const record = Object.fromEntries(METRICS_COLUMNS.map((column, columnIndex) => [column, fields[columnIndex]]))
        if (!isValidIsoTimestamp(record.recorded_at)) throw new Error(`Invalid usage metrics recorded_at at row ${rowNumber}`)
        if (record.record_type === 'account_usage') return []
        if (record.record_type !== 'token_usage') throw new Error(`Invalid usage metrics record_type at row ${rowNumber}`)
        const inputTokens = parseNonNegativeInteger(record.input_tokens, 'input_tokens', rowNumber)
        const cachedInputTokens = parseNonNegativeInteger(record.cached_input_tokens, 'cached_input_tokens', rowNumber)
        const outputTokens = parseNonNegativeInteger(record.output_tokens, 'output_tokens', rowNumber)
        const reasoningTokens = parseNonNegativeInteger(record.reasoning_tokens, 'reasoning_tokens', rowNumber)
        const totalTokens = parseNonNegativeInteger(record.total_tokens, 'total_tokens', rowNumber)
        if (inputTokens + cachedInputTokens + outputTokens + reasoningTokens !== totalTokens) {
            throw new Error(`Inconsistent usage metrics total_tokens at row ${rowNumber}`)
        }

        return [{ recordedAt: record.recorded_at, totalTokens }]
    })
}

function recognizedActivityPath(path: string, config: ProjectConfig) {
    const normalizedPath = normalizePath(path)
    const activityFolder = normalizePath(projectActivityFolder(config.projectFolder))
    const activityPrefix = `${activityFolder}/`
    if (normalizedPath.startsWith(activityPrefix) && !normalizedPath.slice(activityPrefix.length).includes('/')) {
        return activityOriginFromPath(normalizedPath) ? normalizedPath : null
    }
    const releasesFolder = normalizePath(config.releasesFolder)
    const releasePrefix = `${releasesFolder}/`
    if (!normalizedPath.startsWith(releasePrefix)) return null
    const releaseParts = normalizedPath.slice(releasePrefix.length).split('/')
    if (releaseParts.length !== 2 || !/^card__[^/]+\.json$/u.test(releaseParts[1])) return null

    return activityOriginFromPath(normalizedPath) ? normalizedPath : null
}

export function findStatsSourcePaths(repositoryFiles: string[], config: ProjectConfig) {
    const activityPaths = repositoryFiles
        .map((path) => recognizedActivityPath(path, config))
        .filter((path): path is string => path !== null)
        .sort((left, right) => left.localeCompare(right))
    const usageMetricsPath = joinPath(config.projectFolder, USAGE_METRICS_FILE)

    return { activityPaths, usageMetricsPath: repositoryFiles.map(normalizePath).includes(usageMetricsPath) ? usageMetricsPath : null }
}

function utcBucketStart(timestamp: string, granularity: StatsGranularity) {
    const date = new Date(timestamp)
    date.setUTCHours(0, 0, 0, 0)
    if (granularity === 'week') date.setUTCDate(date.getUTCDate() - ((date.getUTCDay() + 6) % 7))
    if (granularity === 'month') date.setUTCDate(1)

    return date.toISOString()
}

function localBucketLabel(utcTimestamp: string) {
    return new Intl.DateTimeFormat(undefined, { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(utcTimestamp))
}

function inRange(timestamp: string, controls: StatsControls) {
    const milliseconds = Date.parse(timestamp)
    if (controls.startUtc && milliseconds < Date.parse(controls.startUtc)) return false
    if (controls.endUtc && milliseconds > Date.parse(controls.endUtc)) return false

    return true
}

function cardLabel(cardInternalId: string, cardPath: string | null, cardsById: Map<string, StatsCardDescriptor>) {
    const card = cardsById.get(cardInternalId)
    if (card) return `${card.visibleId}: ${card.title}`

    return cardPath ?? cardInternalId
}

function actionLabel(actionId: string, storedLabel: string | null) {
    return storedLabel && storedLabel !== actionId ? `${storedLabel} (${actionId})` : actionId
}

function canonicalConversations(activityFiles: CardActivityFile[]) {
    const conversations = new Map<string, TimedConversation>()
    const actionLabels = new Map<string, string>()
    for (const activity of activityFiles) {
        for (const record of activity.records) {
            if (record.type === 'system') continue
            actionLabels.set(record.rootActionId, record.rootActionLabel)
        }
        for (const conversation of activity.conversations) {
            const originIdentity = activity.origin.kind === 'card' ? `card:${activity.origin.cardInternalId}` : 'project'
            const identity = `${originIdentity}:${conversation.id}`
            if (conversations.has(identity)) continue
            const cardInternalId = conversation.cardInternalId ?? (activity.origin.kind === 'card' ? activity.origin.cardInternalId : null)
            conversations.set(identity, {
                actionId: conversation.actionId ?? null,
                actionLabel: conversation.actionId ? actionLabels.get(conversation.actionId) ?? conversation.title : null,
                cardInternalId,
                cardPath: conversation.cardPath,
                completedAt: conversation.completedAt,
                elapsedMs: conversation.timer?.elapsedMs ?? null,
                status: conversation.status,
                totalTokens: conversation.usage?.totalTokens ?? 0,
            })
        }
    }

    return [...conversations.values()]
}

function completedRecords(activityFiles: CardActivityFile[]) {
    const records = new Map<string, {
        actionId: string
        actionLabel: string
        cardInternalId: string | null
        completedAt: string
    }>()
    for (const activity of activityFiles) {
        for (const record of activity.records) {
            if (record.type === 'system' || !COMPLETED_ACTION_STATUSES.has(record.status)) continue
            const originIdentity = record.origin.kind === 'card' ? `card:${record.origin.cardInternalId}` : 'project'
            const identity = `${originIdentity}:${record.runId}`
            if (records.has(identity)) continue
            records.set(identity, {
                actionId: record.rootActionId,
                actionLabel: record.rootActionLabel,
                cardInternalId: record.origin.kind === 'card' ? record.origin.cardInternalId : null,
                completedAt: record.completedAt,
            })
        }
    }

    return [...records.values()]
}

function activityRows(source: LoadedStatsSource, controls: StatsControls): StatsChartRow[] {
    const buckets = new Map<string, { actionCount: number, cards: Set<string>, tokens: number }>()
    if (controls.activityMetric === 'tokens') {
        for (const row of source.tokenRows.filter(({ recordedAt }) => inRange(recordedAt, controls))) {
            const bucket = utcBucketStart(row.recordedAt, controls.granularity)
            const current = buckets.get(bucket) ?? { actionCount: 0, cards: new Set<string>(), tokens: 0 }
            current.tokens += row.totalTokens
            buckets.set(bucket, current)
        }
    } else {
        for (const record of completedRecords(source.activity).filter(({ completedAt }) => inRange(completedAt, controls))) {
            const bucket = utcBucketStart(record.completedAt, controls.granularity)
            const current = buckets.get(bucket) ?? { actionCount: 0, cards: new Set<string>(), tokens: 0 }
            current.actionCount += 1
            if (record.cardInternalId) current.cards.add(record.cardInternalId)
            buckets.set(bucket, current)
        }
    }
    const unit = controls.activityMetric

    return [...buckets.entries()]
        .sort(([left], [right]) => left.localeCompare(right))
        .map(([bucket, values]) => ({
            displayLabel: localBucketLabel(bucket),
            grouping: controls.granularity,
            identity: bucket,
            metric: controls.activityMetric,
            unit,
            utcBucketStart: bucket,
            value: controls.activityMetric === 'cards'
                ? values.cards.size
                : controls.activityMetric === 'actions' ? values.actionCount : values.tokens,
        }))
}

function totalsRows(source: LoadedStatsSource, controls: StatsControls): StatsChartRow[] {
    const cardsById = new Map(source.cards.map((card) => [card.internalId, card]))
    const totals = new Map<string, { label: string, value: number }>()
    const conversations = canonicalConversations(source.activity).filter((conversation) => {
        if (controls.totalsMetric === 'duration') {
            return TERMINAL_CONVERSATION_STATUSES.has(conversation.status)
                && conversation.completedAt !== null
                && inRange(conversation.completedAt, controls)
        }
        if (!controls.startUtc && !controls.endUtc) return true

        return conversation.completedAt !== null && inRange(conversation.completedAt, controls)
    })
    for (const conversation of conversations) {
        const identity = controls.totalsGrouping === 'card' ? conversation.cardInternalId : conversation.actionId
        if (!identity) continue
        const label = controls.totalsGrouping === 'card'
            ? cardLabel(identity, conversation.cardPath, cardsById)
            : actionLabel(identity, conversation.actionLabel)
        const value = controls.totalsMetric === 'duration' ? conversation.elapsedMs : conversation.totalTokens
        if (value === null) continue
        const current = totals.get(identity)
        totals.set(identity, { label, value: (current?.value ?? 0) + value })
    }
    const unit = controls.totalsMetric === 'duration' ? 'milliseconds' : 'tokens'

    return [...totals.entries()]
        .map(([identity, { label, value }]) => ({
            displayLabel: label,
            grouping: controls.totalsGrouping,
            identity,
            metric: controls.totalsMetric,
            unit,
            utcBucketStart: null,
            value,
        } as StatsChartRow))
        .sort((left, right) => right.value - left.value || left.displayLabel.localeCompare(right.displayLabel))
}

function buildSnapshot(source: LoadedStatsSource, controls: StatsControls): ProjectStatsSnapshot {
    const filteredConversations = canonicalConversations(source.activity).filter((conversation) => (
        TERMINAL_CONVERSATION_STATUSES.has(conversation.status)
        && conversation.completedAt !== null
        && inRange(conversation.completedAt, controls)
    ))
    const omittedTimerCount = filteredConversations.filter(({ elapsedMs }) => elapsedMs === null).length
    const rows = controls.dataset === 'activityOverTime' ? activityRows(source, controls) : totalsRows(source, controls)

    return { controls, error: null, omittedTimerCount, rows, status: 'ready', tokenTimeAvailable: source.tokenTimeAvailable }
}

function validateRangeTimestamp(value: string | null, field: string) {
    if (value !== null && !isValidIsoTimestamp(value)) throw new Error(`Invalid stats ${field}`)
}

export class ProjectStatsService extends EventTarget {
    private loadRevision = 0
    private loadedRequest: StatsOpenRequest | null = null
    private projectKey: string | null = null
    private repositoryEvents: EventTarget | null = null
    private snapshot = INITIAL_SNAPSHOT
    private source: LoadedStatsSource | null = null

    getSnapshot = () => this.snapshot

    subscribe = (listener: () => void) => {
        this.addEventListener('changed', listener)

        return () => this.removeEventListener('changed', listener)
    }

    initialize(repositoryEvents: EventTarget) {
        if (this.repositoryEvents === repositoryEvents) return
        this.repositoryEvents?.removeEventListener('repositoryChanged', this.handleRepositoryChanged)
        this.repositoryEvents = repositoryEvents
        this.repositoryEvents.addEventListener('repositoryChanged', this.handleRepositoryChanged)
    }

    async open(request: StatsOpenRequest) {
        this.syncProject(request.project)
        this.loadedRequest = request
        await this.load(request)
    }

    syncProject(project: ProjectReference | null) {
        const projectKey = project ? `${project.id}:${project.branch}` : null
        if (projectKey === this.projectKey) return

        this.projectKey = projectKey
        this.loadRevision += 1
        this.loadedRequest = null
        this.source = null
        this.publish({ ...INITIAL_SNAPSHOT, controls: this.snapshot.controls })
    }

    setControls(changes: Partial<StatsControls>) {
        const controls = { ...this.snapshot.controls, ...changes }
        validateRangeTimestamp(controls.startUtc, 'startUtc')
        validateRangeTimestamp(controls.endUtc, 'endUtc')
        if (controls.startUtc && controls.endUtc && Date.parse(controls.startUtc) > Date.parse(controls.endUtc)) {
            throw new Error('Stats start date must not be after end date')
        }
        if (!this.source) {
            this.publish({ ...this.snapshot, controls })
            return
        }

        this.publish(buildSnapshot(this.source, controls))
    }

    private readonly handleRepositoryChanged = (event: Event) => {
        const request = this.loadedRequest
        if (!request) return
        const path = normalizePath((event as CustomEvent<ProjectWatchEvent>).detail.path)
        const usageMetricsPath = joinPath(request.config.projectFolder, USAGE_METRICS_FILE)
        if (path !== usageMetricsPath && !recognizedActivityPath(path, request.config)) return

        void this.load(request)
    }

    private async load(request: StatsOpenRequest) {
        const revision = ++this.loadRevision
        this.publish({ ...this.snapshot, error: null, rows: [], status: 'loading' })
        try {
            const repositoryFiles = await request.storage.listRepositoryFiles(request.project)
            if (revision !== this.loadRevision || request !== this.loadedRequest) return
            if (!request.storage.loadTextFile) throw new Error('Repository text file loading is not available')
            const { activityPaths, usageMetricsPath } = findStatsSourcePaths(repositoryFiles, request.config)
            const activityFiles = await Promise.all(activityPaths.map(async (path) => {
                const file = await request.storage.loadTextFile?.(request.project, path)
                if (!file) throw new Error(`Activity file could not be loaded: ${path}`)
                const origin = activityOriginFromPath(path)
                if (!origin) throw new Error(`Invalid activity path: ${path}`)

                return parseActivityFile(file.content, origin)
            }))
            const metricsFile = usageMetricsPath
                ? await request.storage.loadTextFile(request.project, usageMetricsPath)
                : null
            const tokenRows = metricsFile ? parseUsageMetrics(metricsFile.content) : []
            if (revision !== this.loadRevision || request !== this.loadedRequest) return

            this.source = { activity: activityFiles, cards: request.cards, tokenRows, tokenTimeAvailable: metricsFile !== null }
            this.publish(buildSnapshot(this.source, this.snapshot.controls))
        } catch (error) {
            if (revision !== this.loadRevision || request !== this.loadedRequest) return
            const normalizedError = error instanceof Error ? error : new Error(String(error))
            this.source = null
            this.publish({ ...this.snapshot, error: normalizedError, rows: [], status: 'error' })
        }
    }

    private publish(snapshot: ProjectStatsSnapshot) {
        this.snapshot = snapshot
        this.dispatchEvent(new Event('changed'))
    }
}

export const projectStatsService = register('projectStatsService', new ProjectStatsService())

import type { StatsChartRow, StatsDataset } from '../../services/stats/project_stats_service'

const CSV_COLUMNS = ['dataset', 'grouping', 'utc_bucket_start', 'identity', 'display_label', 'metric', 'unit', 'value']

function csvValue(value: string | number) {
    const text = String(value)

    return /[",\r\n]/u.test(text) ? `"${text.replaceAll('"', '""')}"` : text
}

export function serializeStatsCsv(dataset: StatsDataset, rows: StatsChartRow[]) {
    const records = rows.map((row) => [
        dataset,
        row.grouping,
        row.utcBucketStart ?? '',
        row.identity,
        row.displayLabel,
        row.metric,
        row.unit,
        row.value,
    ])

    return `${[CSV_COLUMNS, ...records].map((record) => record.map(csvValue).join(',')).join('\r\n')}\r\n`
}

/** Downloads generated stats CSV without writing repository files. */
export function downloadStatsCsv(dataset: StatsDataset, rows: StatsChartRow[]) {
    const blob = new Blob([serializeStatsCsv(dataset, rows)], { type: 'text/csv;charset=utf-8' })
    const url = URL.createObjectURL(blob)
    const anchor = document.createElement('a')
    anchor.download = `md2-stats-${dataset === 'activityOverTime' ? 'activity' : 'totals'}.csv`
    anchor.href = url
    anchor.click()
    URL.revokeObjectURL(url)
}

import { Box, Tooltip, Typography } from '@mui/material'
import type { StatsChartRow } from '../../services/stats/project_stats_service'

const MAXIMUM_BAR_HEIGHT = 240
const MINIMUM_VISIBLE_BAR_HEIGHT = 2

interface StatsBarChartProps {
    rows: StatsChartRow[]
}

function formattedValue(row: StatsChartRow) {
    if (row.unit === 'milliseconds') {
        return new Intl.NumberFormat(undefined, { maximumFractionDigits: 2 }).format(row.value / 1_000) + ' seconds'
    }

    return `${new Intl.NumberFormat().format(row.value)} ${row.unit}`
}

/** Accessible themed bar chart for exact stats rows. */
export function StatsBarChart({ rows }: StatsBarChartProps) {
    const maximumValue = Math.max(...rows.map(({ value }) => value), 0)

    return (
        <Box aria-label="Stats bar chart" role="list" sx={{ alignItems: 'stretch', display: 'flex', flex: 1, gap: 1.5, minHeight: 0, overflowX: 'auto', p: 2 }}>
            {rows.map((row) => {
                const value = formattedValue(row)
                const label = row.displayLabel
                const boundary = row.utcBucketStart ? ` UTC bucket boundary ${row.utcBucketStart}.` : ''
                const height = maximumValue === 0 ? MINIMUM_VISIBLE_BAR_HEIGHT : Math.max(
                    MINIMUM_VISIBLE_BAR_HEIGHT,
                    (row.value / maximumValue) * MAXIMUM_BAR_HEIGHT,
                )

                return (
                    <Box
                        aria-label={`${label}: ${value}.${boundary}`}
                        key={`${row.identity}:${row.metric}`}
                        role="listitem"
                        sx={{ display: 'flex', flex: '0 0 92px', flexDirection: 'column', justifyContent: 'flex-end', minWidth: 0 }}
                    >
                        <Typography align="center" color="text.secondary" title={value} variant="caption">{value}</Typography>
                        <Tooltip title={row.utcBucketStart ? `${value}; UTC bucket boundary ${row.utcBucketStart}` : value}>
                            <Box
                                sx={{
                                    bgcolor: 'primary.main',
                                    borderRadius: 1,
                                    height,
                                    minHeight: MINIMUM_VISIBLE_BAR_HEIGHT,
                                    width: '100%',
                                }}
                            />
                        </Tooltip>
                        <Typography align="center" color="text.secondary" noWrap title={label} variant="caption">{label}</Typography>
                    </Box>
                )
            })}
        </Box>
    )
}

