        if (requestUrl === GITHUB_REPOSITORIES_URL) {
            return Response.json([
                { default_branch: 'trunk', full_name: 'octo/demo', name: 'demo', owner: { login: 'octo' } },
                { default_branch: 'main', full_name: 'octo/notes', name: 'notes', owner: { login: 'octo' } },
