    if ([LEGACY_ACTIVITY_VERSION, SECOND_ACTIVITY_VERSION, PREVIOUS_ACTIVITY_VERSION].includes(value?.version)) {
        return migrateActivityValue(value, expectedOrigin)
    }

    return parseActivityValue(value, expectedOrigin)
}

